// プレゼン教材 第3期（第27〜39週）B1・手本3〜5分
window.PRESENT=(window.PRESENT||[]).concat([
 {week:27, level:"B1", length:"3分", title:"プレゼンの案内と資料送付",
  skill:"発表の前の案内メールと後のお礼メールを書き、発表の最初に「資料を送りました」と伝えられるようになる。",
  lesson:[
   "ビジネスのプレゼンは、話す前と話した後のメールまでが1つの流れです。前のメールでは「いつ・何について・どれくらいの時間か」を伝え、資料を付けて送ります。後のメールでは、お礼と資料、そして次の一歩を書きます。今週の基礎で学んだメールの型（件名 → あいさつ → 用件 → 結び）を、そのまま使いましょう。",
   "発表の最初には、Before we start, I sent you the slides by email. と言い、Did everyone receive them? と確かめます。届いていない人がいれば、その場で I will send them again right away. と答えます。最初に資料の確認をすると、聞き手は安心して話についてこられます。",
   "インドの聞き手とオンラインで話すときは、最初の1分がとても大切です。ゆっくり、はっきり、文を短く切って話しましょう。日本語のように前置きを長くせず、「今日は3つ話します」と要点を先に言うと、聞き手は地図を持って聞くことができます。",
   "メールの件名は短く、名詞でまとめます。Online Presentation on Our Booking System のように、件名だけで中身がわかるようにしましょう。資料は PDF にしておくと、スマートフォンでも開きやすく、相手に親切です。"
  ],
  structure:[{en:"Invitation email",ja:"案内メール（いつ・何を・資料）"},{en:"Opening",ja:"発表の始めのあいさつ"},{en:"Check the materials",ja:"資料が届いたか確かめる"},{en:"Agenda and main points",ja:"今日の流れと中身"},{en:"Thank-you email",ja:"お礼メール（資料・次の一歩）"}],
  phrases:[
   {en:"I am writing to invite you to our online presentation.",ja:"オンラインの発表にご招待したく、ご連絡しました。",note:"案内メールの書き出し。用件を最初の1文で伝える。"},
   {en:"I have attached the slides for your reference.",ja:"ご参考までに、スライドを添付しました。",note:"for your reference は「ご参考までに」。資料を付けたときの決まり文句。"},
   {en:"Please feel free to look at them before the meeting.",ja:"会議の前に、どうぞ自由にご覧ください。",note:"feel free to ＝「遠慮なく〜してください」。押しつけない言い方。"},
   {en:"Before we start, I sent you the slides by email.",ja:"始める前に、スライドはメールでお送りしています。",note:"発表の最初に言う。資料があることを全員に知らせる。"},
   {en:"Did everyone receive the file?",ja:"皆さん、ファイルは届いていますか。",note:"オンラインでは、うなずきが見えにくいので声に出して確かめる。"},
   {en:"If you didn't get it, I will send it again right away.",ja:"届いていなければ、すぐにもう一度お送りします。",note:"right away ＝「すぐに」。困っている人を安心させる。"},
   {en:"You can follow along on page three.",ja:"3ページ目を見ながらついてきてください。",note:"follow along ＝「話についてくる」。ページ番号をはっきり言う。"},
   {en:"As promised, I have attached today's slides.",ja:"お約束どおり、本日のスライドを添付しました。",note:"お礼メールで使う。as promised で約束を守ったことが伝わる。"},
   {en:"Thank you very much for your time today.",ja:"本日はお時間をいただき、ありがとうございました。",note:"お礼メールの最初の1文。your time に感謝するのが英語らしい。"},
   {en:"I look forward to hearing from you.",ja:"お返事をお待ちしております。",note:"メールの結び。この後に Best regards, と名前を書く。"}
  ],
  model:{title:"案内メール → 発表の始め → お礼メール", time:"3分", note:"場面（相手・曜日・時間）は練習用の例です。自分の予定に入れかえましょう。", lines:[
   {en:"[Email before] Subject: Online Presentation on Our Booking System",ja:"【前のメール】件名：予約システムのオンライン発表のご案内"},
   {en:"Dear Dr. Mehta, I hope this email finds you well.",ja:"メータ先生　お元気でお過ごしのことと存じます。"},
   {en:"I am writing to invite your team to a short online presentation about our booking and customer management system.",ja:"私たちの予約・顧客管理システムについての短いオンライン発表に、先生のチームをご招待したく、ご連絡しました。"},
   {en:"It will be on Thursday at 3:00 p.m. India time, and it will take about twenty minutes.",ja:"日時は木曜日のインド時間午後3時で、時間は約20分です。"},
   {en:"I have attached the slides, so please feel free to look at them before the meeting.",ja:"スライドを添付しましたので、会議の前にどうぞご覧ください。"},
   {en:"Please let me know if you have any questions. Best regards, Akihiro Iwata",ja:"ご質問があればお知らせください。よろしくお願いいたします。岩田章弘"},
   {en:"[Presentation] Good afternoon, everyone. Thank you for joining us today.",ja:"【発表】皆さん、こんにちは。本日はご参加いただきありがとうございます。"},
   {en:"My name is Akihiro Iwata. I run an acupuncture and judo therapy clinic in Ozu, a small city in western Japan.",ja:"岩田章弘と申します。西日本の小さな町、大洲で鍼灸整骨院を営んでいます。"},
   {en:"Before we start, I sent you the slides by email yesterday. Did everyone receive them?",ja:"始める前に、昨日スライドをメールでお送りしました。皆さん、届いていますか。"},
   {en:"If you didn't get them, please tell me now, and I will send them again right away.",ja:"届いていなければ今おっしゃってください。すぐにもう一度お送りします。"},
   {en:"You can follow along on the screen, or open the file on your own computer.",ja:"画面を見ながらでも、ご自分のパソコンでファイルを開いてでも、ついてきていただけます。"},
   {en:"Today I would like to talk about three things.",ja:"今日は3つのことをお話しします。"},
   {en:"First, why I made this system. Second, what it can do. Third, how your clinic can try it.",ja:"1つ目は、このシステムを作った理由。2つ目は、できること。3つ目は、先生の院で試す方法です。"},
   {en:"At my clinic, I check sales, the number of visits, and the return rate every day.",ja:"私の院では、売上・来院数・再来院率を毎日見ています。"},
   {en:"Writing these numbers by hand took too much time, so I built a simple system to do it.",ja:"手で数字を書くのは時間がかかりすぎたので、それをする簡単なシステムを作りました。"},
   {en:"Now my partner clinics in Japan use the same system for booking and customer records.",ja:"今では日本の提携院が、同じシステムを予約と顧客の記録に使っています。"},
   {en:"Please look at page three of the slides. This is the booking screen.",ja:"スライドの3ページ目をご覧ください。これが予約の画面です。"},
   {en:"Patients can choose a date and time on their phone, and the clinic gets a message at once.",ja:"患者さんはスマートフォンで日時を選べて、院にはすぐに知らせが届きます。"},
   {en:"I will take questions at the end, so please write them down as we go.",ja:"ご質問は最後にお受けしますので、途中で書き留めておいてください。"},
   {en:"[Email after] Subject: Thank You and Today's Slides",ja:"【後のメール】件名：お礼と本日のスライド"},
   {en:"Dear Dr. Mehta, thank you very much for your time today.",ja:"メータ先生　本日はお時間をいただき、ありがとうございました。"},
   {en:"As promised, I have attached the slides and a short summary of our discussion.",ja:"お約束どおり、スライドと話し合いの短いまとめを添付しました。"},
   {en:"If you would like to see the system in action, I can show you a demo next week.",ja:"システムが動くところをご覧になりたければ、来週お見せできます。"},
   {en:"I look forward to hearing from you. Best regards, Akihiro Iwata",ja:"お返事をお待ちしております。よろしくお願いいたします。岩田章弘"}
  ]},
  task:"インドの院長あてに、予約・顧客管理システムの発表の案内メールを書き、発表の最初の1分（あいさつ・資料の確認・今日の3つの話）と、お礼メールを作る。全体で3分。",
  taskEn:"Write an invitation email to a clinic director in India about a presentation on my booking system. Then give the first minute of the presentation, including checking that everyone has the slides. Finish with a thank-you email. About three minutes in total.",
  qa:[
   {q:"Could you send the slides as a PDF?",a:"Of course. I will send a PDF version right after this meeting.",ja:"質問：スライドを PDF で送っていただけますか。／答え：もちろんです。この会議のすぐ後に PDF 版をお送りします。"},
   {q:"Can I share the slides with my manager?",a:"Yes, please do. They are for your whole team.",ja:"質問：スライドを上司と共有してもいいですか。／答え：はい、どうぞ。チームの皆さん向けの資料です。"},
   {q:"I didn't receive your email. Which address did you use?",a:"I'm sorry about that. Let me check the address and send it again now.",ja:"質問：メールが届いていません。どのアドレスに送りましたか。／答え：申し訳ありません。アドレスを確かめて、今もう一度お送りします。"}
  ],
  check:["案内メールに「いつ・何について・どれくらいの時間か」が入っているか","発表の最初に「資料を送りました」「届いていますか」と言えたか","「今日は3つ話します」と、要点を先に言えたか","お礼メールに、お礼・資料・次の一歩の3つが入っているか","ゆっくり、文を短く切って話せたか（録音で確かめる）"],
  slide:"1枚目は題と自分の名前だけ。右下に「スライドはメールでお送りしています」と小さく書いておくと、言い忘れても伝わります。"},

 {week:28, level:"B1", length:"3分", title:"協力をお願いするプレゼン",
  skill:"Can you → Could you → We would appreciate it if… のていねいさの階段を使い分けて、相手に協力をお願いできるようになる。",
  lesson:[
   "お願いの英語には、ていねいさの階段があります。Can you…? は親しい相手や小さなお願い、Could you…? は仕事の基本、We would appreciate it if… はお願いが大きいときや相手が目上のときに使います。大きなお願いほど、上の段の言い方を選びましょう。",
   "お願いのプレゼンは「背景 → お願い → 理由 → 相手にとっての良いこと → 締め切り」の順で組み立てます。お願いだけを並べると、相手は「なぜ？」と思います。1つのお願いに、1つの理由をつけるのがコツです。",
   "インドの聞き手には、お願いの数を最初に言うと伝わりやすくなります。I have three requests. と言ってから、First, Second, Third と番号をつけて話しましょう。最後にもう一度、3つを短く並べて言い直すと、聞き逃した人も安心です。",
   "相手が忙しいことをわかっている、と一言そえるのも大切です。I know your team is very busy. と言い、難しければ別の方法を一緒に考える、と伝えると、断りやすく、受けやすい雰囲気になります。"
  ],
  structure:[{en:"Thanks and background",ja:"お礼と背景"},{en:"Number of requests",ja:"お願いの数を先に言う"},{en:"Request + reason",ja:"お願い＋理由（1つずつ）"},{en:"What you will get",ja:"相手にとっての良いこと"},{en:"Summary and deadline",ja:"まとめと返事の期限"}],
  phrases:[
   {en:"I need your cooperation in three areas.",ja:"3つの点でご協力をお願いしたいです。",note:"お願いの数を先に言う。聞き手が数えながら聞ける。"},
   {en:"Can you choose five staff members?",ja:"スタッフを5人選んでもらえますか。",note:"階段の1段目。小さなお願い・親しい相手に。"},
   {en:"Could you share some guest comments with me?",ja:"お客様の感想をいくつか共有していただけますか。",note:"階段の2段目。仕事のお願いの基本。"},
   {en:"We would appreciate it if your manager could join.",ja:"支配人にご参加いただけるとありがたいです。",note:"階段の3段目。目上の人・大きなお願いに。if の後は could。"},
   {en:"Would you be able to send it by Friday?",ja:"金曜日までにお送りいただくことはできますか。",note:"相手の都合を気づかう言い方。期限のあるお願いに。"},
   {en:"I know your team is very busy.",ja:"皆さんがとてもお忙しいことは承知しています。",note:"お願いの前にひと言。相手への気づかいが伝わる。"},
   {en:"Here is what you will get in return.",ja:"その代わりに、こちらからお渡しできるものです。",note:"in return ＝「お返しに」。相手の良いことを話す前に。"},
   {en:"I will keep the information private.",ja:"情報は外に出さないようにします。",note:"個人情報や社内の情報をお願いするときに必ず言う。"},
   {en:"Could you let me know by next Friday?",ja:"来週の金曜日までにお知らせいただけますか。",note:"最後に返事の期限をはっきり言う。"},
   {en:"If any request is difficult, please tell me.",ja:"難しいお願いがあれば、おっしゃってください。",note:"断りやすくすることで、かえって受けてもらいやすくなる。"}
  ],
  model:{title:"インドのホテルに研修への協力をお願いする", time:"3分", note:"人数・期間などは練習用の例です。自分の計画に入れかえましょう。", lines:[
   {en:"Good morning, everyone. Thank you for having me again.",ja:"皆さん、おはようございます。また呼んでいただき、ありがとうございます。"},
   {en:"Last month, we talked about how to welcome Japanese guests at your hotel.",ja:"先月は、このホテルで日本人のお客様をどう迎えるかについて話しました。"},
   {en:"Today I have a few requests, and I would like to explain why they matter.",ja:"今日はいくつかお願いがあり、それがなぜ大切かをご説明したいと思います。"},
   {en:"Japanese guests often notice small things, like a clean entrance or a warm greeting by name.",ja:"日本人のお客様は、きれいな入口や名前を呼んでの温かいあいさつなど、小さなことによく気づきます。"},
   {en:"To help your team with this, I am planning a short omotenashi training here, in two half-day sessions.",ja:"そのお手伝いとして、こちらで半日ずつ2回の、短いおもてなし研修を計画しています。"},
   {en:"For this training to work well, I need your cooperation in three areas.",ja:"この研修がうまくいくために、3つの点でご協力をお願いしたいです。"},
   {en:"First, can you choose five staff members from the front desk and the restaurant?",ja:"1つ目、フロントとレストランから、スタッフを5人選んでもらえますか。"},
   {en:"They will join both sessions, so please choose people who meet guests every day.",ja:"2回とも参加してもらうので、毎日お客様と接する人を選んでください。"},
   {en:"Second, could you share some guest comments from the last six months?",ja:"2つ目、この半年のお客様の感想をいくつか共有していただけますか。"},
   {en:"Real comments help me understand what your guests like and what they don't.",ja:"本物の感想があると、お客様が何を好み、何を好まないかがわかります。"},
   {en:"For example, if many guests mention slow check-in, we can practice that part in the training.",ja:"たとえば、チェックインが遅いという声が多ければ、研修でその部分を練習できます。"},
   {en:"Of course, I will not use guest names, and I will keep the information private.",ja:"もちろん、お客様の名前は使いませんし、情報は外に出しません。"},
   {en:"Third, we would appreciate it if your general manager could join the first hour of the training.",ja:"3つ目、研修の最初の1時間に総支配人にご参加いただけると、ありがたいです。"},
   {en:"When the manager joins, the staff can see that this training is important for the hotel.",ja:"支配人が参加すると、スタッフはこの研修がホテルにとって大切だとわかります。"},
   {en:"Even a short welcome speech from the manager makes a big difference.",ja:"支配人の短い歓迎のあいさつだけでも、大きな違いが出ます。"},
   {en:"I know your team is very busy, so I will keep each session to three hours.",ja:"皆さんがとてもお忙しいことは承知していますので、各回は3時間に収めます。"},
   {en:"Now, here is what you will get in return.",ja:"では、その代わりにお渡しできるものです。"},
   {en:"Your staff will learn simple Japanese greetings and how to notice what guests need before they ask.",ja:"スタッフは、簡単な日本語のあいさつと、お客様が頼む前に必要なことに気づく方法を学べます。"},
   {en:"After the training, I will send you a short report with ideas for each team.",ja:"研修の後には、チームごとのアイデアを入れた短い報告書をお送りします。"},
   {en:"The report will also include three small actions your team can start the next day.",ja:"報告書には、次の日から始められる3つの小さな行動も入れます。"},
   {en:"Let me sum up my three requests.",ja:"3つのお願いをまとめます。"},
   {en:"Five staff members, guest comments from the last six months, and one hour of your manager's time.",ja:"スタッフ5人、この半年のお客様の感想、そして支配人の1時間です。"},
   {en:"Could you let me know by next Friday if this is possible?",ja:"これが可能かどうか、来週の金曜日までにお知らせいただけますか。"},
   {en:"That way, I can book my trip to India and prepare the training materials in time.",ja:"そうすれば、インドへの旅の予約と研修の資料の準備が間に合います。"},
   {en:"If any request is difficult, please tell me. We can find another way together.",ja:"難しいお願いがあれば、おっしゃってください。一緒に別の方法を考えましょう。"},
   {en:"Thank you very much for your support. I'm happy to answer any questions.",ja:"ご協力に心から感謝します。どんなご質問にもお答えします。"}
  ]},
  task:"インドのホテルに、おもてなし研修への協力（スタッフを選ぶ・感想を共有する・支配人の参加）をお願いする3分のプレゼンを作る。お願いには必ず理由をつけ、ていねいさの階段を3段とも使う。",
  taskEn:"Give a three-minute presentation asking an Indian hotel to cooperate with an omotenashi training. Make three requests, give a reason for each, and use Can you, Could you, and We would appreciate it if.",
  qa:[
   {q:"How long is each session?",a:"About three hours. We can do them in the morning, before the busy evening time.",ja:"質問：各回はどれくらいの長さですか。／答え：約3時間です。夜の忙しい時間の前、午前中に行えます。"},
   {q:"Can more than five staff members join?",a:"Yes, up to ten is fine. Five is the minimum.",ja:"質問：5人より多く参加してもいいですか。／答え：はい、10人までなら大丈夫です。5人は最低の人数です。"},
   {q:"What if our general manager can't join?",a:"Then a senior manager is fine. Someone who can share the message with the team.",ja:"質問：総支配人が参加できない場合は？／答え：それなら上の立場の方で大丈夫です。チームに思いを伝えられる方をお願いします。"}
  ],
  check:["お願いの数を最初に言えたか","Can you・Could you・We would appreciate it if の3段を使い分けたか","お願いの1つずつに理由をつけたか","相手にとっての良いことを話したか","最後にお願いをまとめて、返事の期限を言えたか"],
  slide:"お願いを3つの箱に分け、番号と短い言葉（5 staff / Guest comments / 1 hour）だけを書きます。理由は口で話しましょう。"},

 {week:29, level:"B1", length:"3分", title:"オンラインでプレゼンする",
  skill:"画面共有・音の確認・トラブルのときの英語を使って、オンラインのプレゼンを落ち着いて進められるようになる。",
  lesson:[
   "インドの取引先とのプレゼンは、ほとんどがオンラインです。最初に Can you hear me clearly? と音を確かめ、画面を共有したら Can everyone see my screen? と聞きます。この2つの確認だけで、聞き手は「この人は慣れている」と安心します。",
   "トラブルは必ず起きます。画面が止まったら It seems my screen has frozen. と言い、Let me stop sharing and share again. と次に何をするかを伝えます。黙ったまま直そうとすると、聞き手は待つしかありません。何が起きているかを声に出すのがコツです。",
   "インドの通信は、場所や時間によって音が途切れることがあります。ふだんより少しゆっくり、ひと言ずつはっきり話しましょう。数字や名前は2回言う、大事な所でチャットに書く、という工夫も役に立ちます。",
   "話の途中と最後に、確認をはさみましょう。Was my voice clear enough? や Please let me know in the chat. と聞くと、聞き手が反応しやすくなります。最後は I will stop sharing my screen now. と言ってから共有を止め、顔を見ながら質問を受けます。"
  ],
  structure:[{en:"Sound and screen check",ja:"音と画面の確認"},{en:"Meeting rules",ja:"ミュート・質問のしかた"},{en:"Main points",ja:"本題（3つの点）"},{en:"Trouble and recovery",ja:"トラブルと立て直し"},{en:"Stop sharing and Q&A",ja:"共有を止めて質疑応答"}],
  phrases:[
   {en:"Can you hear me clearly?",ja:"私の声ははっきり聞こえますか。",note:"最初のひと言。返事を待ってから話し始める。"},
   {en:"Let me share my screen.",ja:"画面を共有します。",note:"何をするか先に言ってから操作する。"},
   {en:"Can everyone see my screen?",ja:"皆さん、私の画面が見えますか。",note:"共有したら必ず確かめる。"},
   {en:"Please mute your microphone when you are not speaking.",ja:"話していないときは、マイクをミュートにしてください。",note:"雑音を防ぐお願い。最初に一度だけ言う。"},
   {en:"Please type your questions in the chat.",ja:"ご質問はチャットに書いてください。",note:"音が悪いときでも質問を受けられる。"},
   {en:"It seems my screen has frozen.",ja:"画面が止まってしまったようです。",note:"トラブルが起きたら、まず何が起きたかを言う。"},
   {en:"Sorry, I think my connection is a little slow.",ja:"すみません、通信が少し遅いようです。",note:"謝りすぎず、短く説明する。"},
   {en:"Let me stop sharing and share again.",ja:"共有を止めて、もう一度共有します。",note:"次に何をするかを伝えると、聞き手が待てる。"},
   {en:"You're on mute.",ja:"ミュートになっていますよ。",note:"相手の声が聞こえないとき。やさしく短く伝える。"},
   {en:"I will stop sharing my screen now.",ja:"では、画面の共有を止めます。",note:"質疑応答の前に。顔を見て話す時間に切り替える。"}
  ],
  model:{title:"インドのレストランへのオンライン発表（トラブルあり）", time:"3分", note:"名前や場面は練習用の例です。", lines:[
   {en:"Hello, everyone. Can you hear me clearly?",ja:"皆さん、こんにちは。私の声ははっきり聞こえますか。"},
   {en:"Great, thank you. Let me share my screen now.",ja:"よかった、ありがとうございます。では画面を共有します。"},
   {en:"Can everyone see my screen? You should see the title slide, Welcoming Japanese Guests.",ja:"皆さん、画面が見えますか。「日本人のお客様を迎える」という題のスライドが見えるはずです。"},
   {en:"If the slide looks small, you can make it full screen with the button at the bottom.",ja:"スライドが小さく見えたら、下のボタンで全画面にできます。"},
   {en:"Before we start, a quick request. Please mute your microphone when you are not speaking.",ja:"始める前に、ひとつお願いです。話していないときは、マイクをミュートにしてください。"},
   {en:"If you have a question, please type it in the chat or raise your hand.",ja:"ご質問があれば、チャットに書くか、手を挙げてください。"},
   {en:"Today's topic is how your restaurants can welcome Japanese guests.",ja:"今日の話題は、皆さんのレストランが日本人のお客様をどう迎えるかです。"},
   {en:"I will talk for about fifteen minutes, and then we will have time for questions.",ja:"約15分お話しし、その後に質問の時間をとります。"},
   {en:"Let's begin with the first point: the first thirty seconds.",ja:"1つ目の点、最初の30秒から始めましょう。"},
   {en:"Japanese guests decide a lot in the first thirty seconds after they walk in.",ja:"日本人のお客様は、店に入ってからの最初の30秒で多くのことを決めます。"},
   {en:"A smile, eye contact, and a clear greeting make them feel safe.",ja:"笑顔と目を合わせること、はっきりしたあいさつで、お客様は安心します。"},
   {en:"Many Japanese people are a little shy in a new place, so a warm first moment really helps.",ja:"日本人の多くは初めての場所で少し人見知りなので、温かい最初の瞬間がとても助けになります。"},
   {en:"Next, please look at this slide. It shows a simple Japanese greeting: irasshaimase.",ja:"次に、このスライドをご覧ください。簡単な日本語のあいさつ「いらっしゃいませ」です。"},
   {en:"Oh, it seems my screen has frozen. Can you still see the slide?",ja:"あれ、画面が止まってしまったようです。まだスライドは見えますか。"},
   {en:"Sorry about that. I think my internet connection is a little slow.",ja:"すみません。インターネットの通信が少し遅いようです。"},
   {en:"Let me stop sharing and share again. Please give me one moment.",ja:"共有を止めて、もう一度共有します。少しお待ちください。"},
   {en:"Okay, is it working now? Please let me know in the chat.",ja:"はい、今は見えていますか。チャットで教えてください。"},
   {en:"Thank you, Raj. Let's continue from the greeting slide.",ja:"ラジさん、ありがとうございます。あいさつのスライドから続けます。"},
   {en:"If the screen freezes again, I will describe the slide in words, so please keep listening.",ja:"もしまた画面が止まったら、スライドを言葉で説明しますので、そのまま聞いていてください。"},
   {en:"The second point is the menu. Japanese guests like menus with photos and clear prices.",ja:"2つ目の点はメニューです。日本人のお客様は、写真とわかりやすい値段のあるメニューを好みます。"},
   {en:"They also like to know if a dish is spicy, so a simple chili mark helps a lot.",ja:"料理が辛いかどうかも知りたいので、簡単な唐辛子のマークがとても役立ちます。"},
   {en:"Some guests also cannot eat certain foods, so a short note about ingredients is very kind.",ja:"食べられないものがあるお客様もいるので、材料についての短い説明があるととても親切です。"},
   {en:"The third point is the goodbye. A short bow and a thank-you at the door stay in their memory.",ja:"3つ目の点はお見送りです。入口での軽いおじぎとお礼の言葉は、記憶に残ります。"},
   {en:"Before I finish, let me check. Was my voice clear enough today?",ja:"終わる前に確かめさせてください。今日の私の声は、十分はっきり聞こえましたか。"},
   {en:"Thank you. I see some thumbs up in the chat. Great.",ja:"ありがとうございます。チャットにいいねの印がいくつか見えます。よかったです。"},
   {en:"Let me quickly repeat the three points: the first thirty seconds, the menu, and the goodbye.",ja:"3つの点を手短にくり返します。最初の30秒、メニュー、そしてお見送りです。"},
   {en:"I will stop sharing my screen now, so we can see each other's faces.",ja:"では画面の共有を止めますので、お互いの顔を見て話しましょう。"},
   {en:"Thank you for your patience today. Now, I'm happy to take your questions.",ja:"今日はお待ちいただき、ありがとうございました。では、ご質問をお受けします。"}
  ]},
  task:"インドのレストランのスタッフに向けて、オンラインで3分の発表をする。音と画面の確認、ミュートのお願い、途中で画面が止まったときの立て直し、最後の共有停止までを入れる。",
  taskEn:"Give a three-minute online presentation to restaurant staff in India. Check the sound and screen, ask people to mute, recover from a frozen screen in the middle, and stop sharing before Q&A.",
  qa:[
   {q:"Your voice was cutting out. Could you repeat the last point?",a:"Sure. The last point was the goodbye: a short bow and a thank-you at the door.",ja:"質問：声が途切れていました。最後の点をくり返していただけますか。／答え：はい。最後の点はお見送りで、入口での軽いおじぎとお礼の言葉です。"},
   {q:"Can we use these slides for our staff training?",a:"Yes, of course. I will send you the file after the meeting.",ja:"質問：このスライドをスタッフ研修に使ってもいいですか。／答え：はい、もちろんです。会議の後にファイルをお送りします。"},
   {q:"Will you record this meeting?",a:"Only if everyone agrees. If you'd like a recording, I can send the link tomorrow.",ja:"質問：この会議は録画しますか。／答え：皆さんが同意すればです。録画が必要なら、明日リンクをお送りできます。"}
  ],
  check:["最初に音と画面の2つを確かめたか","ミュートと質問のしかたを最初にお願いしたか","画面が止まったとき、黙らずに何が起きたかを言えたか","ふだんよりゆっくり、はっきり話せたか","共有を止めると言ってから質疑応答に入れたか"],
  slide:"1枚目は題だけを大きく。画面が小さく見える人もいるので、文字は大きく、1枚に1つの話だけにします。"},

 {week:30, level:"B1", length:"3〜4分", title:"意見と根拠を示す",
  skill:"I believe… because… For example… の型で、主張・理由・例をそろえて意見を伝えられるようになる。",
  lesson:[
   "意見を伝えるプレゼンは「主張 → 理由 → 例 → もう一度主張」の順が基本です。最初に I believe… と自分の考えをはっきり言い、because… で理由、For example… で例を出します。日本語のように理由を先に長く話すと、聞き手は「結局どう思っているの？」と迷ってしまいます。",
   "理由は2つか3つにしぼり、First, Second, Third と番号をつけましょう。例は具体的なほど伝わります。数字を使うときは、練習用の例であることを自分でわかったうえで、本番では自分の本当の数字に入れかえます。",
   "反対の意見が出そうなときは、自分から先に言ってしまうのも上手な方法です。Some of you may worry that… と相手の心配を言い、That's a fair point. と受け止めてから、自分の答えを話します。インドのビジネスの場では、議論はよくあることです。反対されても落ち着いて、相手の意見を聞く姿勢を見せましょう。",
   "最後は Does anyone see it differently? と、相手の意見を聞いて終わります。オンラインでは発言が重なりやすいので、名前を呼んで聞く、チャットにも書いてもらう、などの工夫をしましょう。"
  ],
  structure:[{en:"Opinion",ja:"主張（I believe…）"},{en:"Reasons",ja:"理由（because… 2〜3つ）"},{en:"Example",ja:"例（For example…）"},{en:"Answer a worry",ja:"心配に先に答える"},{en:"Suggestion and question",ja:"提案と、相手への問いかけ"}],
  phrases:[
   {en:"I believe every clinic should contact new patients.",ja:"すべての院が、新しい患者さんに連絡するべきだと私は考えます。",note:"主張は最初に、はっきりと。I believe は I think より強い。"},
   {en:"Let me explain why I think so.",ja:"なぜそう考えるのか、ご説明します。",note:"主張から理由へ移るつなぎの言葉。"},
   {en:"The main reason is that patients often forget.",ja:"一番の理由は、患者さんがよく忘れてしまうことです。",note:"The main reason is that ＋ 文。理由が1つのときに便利。"},
   {en:"Let me give you an example.",ja:"例を1つお話しします。",note:"例に入る前のひと言。聞き手の集中が戻る。"},
   {en:"In my opinion, a short message feels kind.",ja:"私の考えでは、短いメッセージは親切に感じられます。",note:"In my opinion は「自分の考えです」と少しやわらげる。"},
   {en:"Some of you may worry that it feels pushy.",ja:"押しつけがましく感じるのでは、と心配な方もいるでしょう。",note:"反対意見を先に言う。pushy ＝「押しつけがましい」。"},
   {en:"That's a fair point.",ja:"もっともなご意見です。",note:"反対意見を受け止めるひと言。この後に自分の答えを言う。"},
   {en:"That is why I suggest a very short message.",ja:"だからこそ、ごく短いメッセージを提案します。",note:"That is why ＝「だからこそ」。理由から提案へつなぐ。"},
   {en:"I see it a little differently.",ja:"私は少し違う見方をしています。",note:"反対するときのやわらかい言い方。"},
   {en:"Does anyone see it differently?",ja:"違う見方の方はいらっしゃいますか。",note:"最後に相手の意見を聞いて、話し合いにつなげる。"}
  ],
  model:{title:"提携院の会議で意見を述べる：初回の後に連絡をしよう", time:"3〜4分", note:"数字は練習用の例です。自分の数字に入れかえましょう。", lines:[
   {en:"Good evening, everyone. Thank you for coming to tonight's partner meeting.",ja:"皆さん、こんばんは。今夜の提携院の会議にお集まりいただき、ありがとうございます。"},
   {en:"Today I want to share one opinion, and I hope it starts a good discussion.",ja:"今日は1つの意見をお話しします。良い話し合いのきっかけになればうれしいです。"},
   {en:"I believe every clinic should contact new patients within three days after their first visit.",ja:"すべての院が、新しい患者さんに初回の来院から3日以内に連絡するべきだと、私は考えます。"},
   {en:"Let me explain why I think so.",ja:"なぜそう考えるのか、ご説明します。"},
   {en:"First, the return rate is one of the most important numbers for a small clinic.",ja:"1つ目に、再来院率は小さな院にとって、もっとも大切な数字の1つです。"},
   {en:"Getting a new patient costs much more than keeping a patient who already trusts us.",ja:"新しい患者さんを得るのは、すでに信頼してくれている患者さんに来続けてもらうより、ずっと費用がかかります。"},
   {en:"Advertising, discounts, and time for first visits all cost money.",ja:"広告、割引、初回の来院にかかる時間は、どれもお金がかかります。"},
   {en:"Second, many patients don't come back simply because they forget, not because they are unhappy.",ja:"2つ目に、多くの患者さんが来なくなるのは、不満だからではなく、ただ忘れてしまうからです。"},
   {en:"A short message reminds them that we care, and it makes the next booking easy.",ja:"短いメッセージは、私たちが気にかけていることを思い出させ、次の予約を簡単にします。"},
   {en:"Most people feel happy when someone remembers them and asks how they are.",ja:"たいていの人は、誰かが覚えていて調子をたずねてくれると、うれしく感じます。"},
   {en:"Third, our booking system can send this message automatically, so it doesn't take staff time.",ja:"3つ目に、私たちの予約システムはこのメッセージを自動で送れるので、スタッフの時間をとりません。"},
   {en:"Staff only need to check the message once, and the system does the rest.",ja:"スタッフはメッセージを一度確かめるだけで、あとはシステムがしてくれます。"},
   {en:"Let me give you an example.",ja:"例を1つお話しします。"},
   {en:"Imagine a clinic that starts sending a short thank-you message after each first visit.",ja:"初回の来院のたびに、短いお礼のメッセージを送り始めた院を考えてみてください。"},
   {en:"In the message, the clinic asks how the patient feels and shares a link to book again.",ja:"メッセージでは、体の調子をたずね、次の予約のリンクを送ります。"},
   {en:"After three months, its return rate goes up from 45 percent to 60 percent.",ja:"3か月後、再来院率が45パーセントから60パーセントに上がります。"},
   {en:"Of course, one clinic is not enough to say it works everywhere.",ja:"もちろん、1つの院だけでは、どこでもうまくいくとは言えません。"},
   {en:"Each clinic has different patients, different staff, and a different town.",ja:"院ごとに、患者さんも、スタッフも、町も違います。"},
   {en:"However, I think the idea is simple enough to try at every clinic.",ja:"それでも、この考えはどの院でも試せるくらい簡単だと思います。"},
   {en:"Some of you may worry that patients will feel the message is pushy.",ja:"患者さんがメッセージを押しつけがましく感じるのでは、と心配な方もいるでしょう。"},
   {en:"That's a fair point. That is why I suggest a very short message with no sales talk.",ja:"もっともなご意見です。だからこそ、売り込みのない、ごく短いメッセージを提案します。"},
   {en:"For example: Thank you for visiting us today. How are you feeling? Please take care.",ja:"たとえば「本日はご来院ありがとうございました。お体の調子はいかがですか。どうぞお大事に」。"},
   {en:"In my opinion, a message like this feels kind, not pushy.",ja:"私の考えでは、このようなメッセージは押しつけではなく、親切に感じられます。"},
   {en:"It's like a friend asking, how are you? Nobody feels pushed by that.",ja:"友だちが「元気？」と聞くようなものです。それで押しつけられたと感じる人はいません。"},
   {en:"So here is my suggestion. Let's try it for three months at all partner clinics.",ja:"そこで提案です。すべての提携院で、3か月試してみましょう。"},
   {en:"Then, at our next meeting, we can compare the numbers and decide together.",ja:"そして次の会議で数字を比べて、一緒に決めましょう。"},
   {en:"If the numbers don't improve, we can stop. There is very little risk in trying.",ja:"数字が良くならなければ、やめればいいのです。試すことのリスクはとても小さいです。"},
   {en:"I will prepare a simple message template, so no clinic has to start from zero.",ja:"簡単なメッセージのひな形を用意するので、どの院もゼロから始める必要はありません。"},
   {en:"That's my opinion. I would love to hear yours. Does anyone see it differently?",ja:"以上が私の意見です。皆さんのご意見もぜひ聞かせてください。違う見方の方はいらっしゃいますか。"}
  ]},
  task:"提携院の会議で「初回の来院の後に短い連絡をしよう」という意見を、主張→理由3つ→例→心配への答え→提案の順で、3〜4分で話す。",
  taskEn:"At a partner clinic meeting, give your opinion that clinics should contact new patients after their first visit. Use the order: opinion, three reasons, an example, an answer to a worry, and a suggestion. Three to four minutes.",
  qa:[
   {q:"What if a patient doesn't want any messages?",a:"Then we stop. We ask at the front desk first, and we send only one message.",ja:"質問：患者さんがメッセージを望まない場合は？／答え：そのときは送りません。まず受付で確認し、送るのも1回だけです。"},
   {q:"Who writes the message?",a:"I'll share a simple template. Each clinic can change it a little.",ja:"質問：メッセージは誰が書くのですか。／答え：簡単なひな形をお渡しします。各院で少し変えてもかまいません。"},
   {q:"How do we measure the result?",a:"The system shows the return rate every month, so we can compare before and after.",ja:"質問：結果はどう測るのですか。／答え：システムが毎月の再来院率を出すので、前と後を比べられます。"},
   {q:"Isn't three days too soon?",a:"I see it a little differently. Within three days, patients still remember the visit well.",ja:"質問：3日は早すぎませんか。／答え：私は少し違う見方をしています。3日以内なら、患者さんはまだ来院をよく覚えています。"}
  ],
  check:["最初の30秒で I believe… と主張を言えたか","理由に First, Second, Third と番号をつけたか","For example… で具体的な例を出せたか","反対の心配に先に答えられたか","最後に相手の意見を聞いて終われたか"],
  slide:"1枚目に主張を1文で大きく書き、2枚目に理由を3つ、3枚目に例の数字（前と後）を棒グラフで見せます。"},

 {week:31, level:"B1", length:"4分（5分の型）", title:"会社紹介プレゼンの完成",
  skill:"誰が → どこで → 何を → 強み → これから、の型で、自分と事業を4〜5分で紹介できるようになる。",
  lesson:[
   "今週は、これまでの自己紹介をまとめて「会社紹介プレゼン」を完成させます。型は5つ。誰が（自分の資格と経験）、どこで（院の場所と開業）、何を（3つの仕事）、強み（3つ）、これから（目指すこと）です。この順番を守れば、どんな相手にも5分で自分を伝えられます。",
   "仕事が多い人ほど、話が散らかりやすくなります。My work has three parts. と最初に数を言い、The first part is… と1つずつ話しましょう。くわしい説明は質問されたときに答えればよいので、ここでは短く、はっきりと。",
   "インドの聞き手には、日本の資格や地名は聞きなれない言葉です。judo therapist や Ozu のような言葉は、ゆっくり言い、短い説明をつけます（These are national licenses in Japan. / a quiet city on the island of Shikoku）。最初に Namaste とひと言あいさつすると、場がやわらぎます。",
   "最後は「大切にしていること」で締めると、心に残ります。I do my best for the person in front of me. は、岩田さんの仕事全部をつなぐ1文です。強みの話のあとにこの1文を置くと、数字や資格だけでない人柄が伝わります。"
  ],
  structure:[{en:"Who",ja:"誰が（資格・経験）"},{en:"Where",ja:"どこで（場所・開業）"},{en:"What",ja:"何を（3つの仕事）"},{en:"Strengths",ja:"強み（3つ）"},{en:"Future",ja:"これから・大切にしていること"}],
  phrases:[
   {en:"I'd like to introduce myself and my work.",ja:"私自身と私の仕事をご紹介します。",note:"会社紹介の最初のひと言。"},
   {en:"I'm a licensed acupuncturist and judo therapist.",ja:"私は国家資格をもつ鍼灸師・柔道整復師です。",note:"licensed で「資格をもつ」。ゆっくり言う。"},
   {en:"Before I opened my clinic, I worked as an athletic trainer.",ja:"院を開く前は、アスレティックトレーナーとして働いていました。",note:"経歴を1文で。Before ＋ 文 ＋ 過去形。"},
   {en:"My clinic is located near Iyo-Ozu Station.",ja:"私の院は伊予大洲駅の近くにあります。",note:"be located ＝「〜にある」。場所の紹介に。"},
   {en:"I opened the clinic in October 2018.",ja:"2018年10月に院を開きました。",note:"年は twenty eighteen と読む。"},
   {en:"My work has three main parts.",ja:"私の仕事には、主に3つの柱があります。",note:"数を先に言い、聞き手に地図を渡す。"},
   {en:"We offer acupuncture and posture care.",ja:"鍼灸と姿勢のケアを行っています。",note:"We offer ＋ 名詞。メニューの紹介に。"},
   {en:"I'd like to mention three strengths.",ja:"強みを3つお伝えします。",note:"強みに入る合図。"},
   {en:"Looking ahead, we plan to start with a small project.",ja:"これからは、小さな事業から始める予定です。",note:"Looking ahead ＝「これから先は」。未来の話に。"},
   {en:"I do my best for the person in front of me.",ja:"目の前の人に全力を尽くします。",note:"大切にしていることを1文で。締めに使う。"}
  ],
  model:{title:"岩田章弘の会社紹介（オンライン商談）", time:"4分", note:"", lines:[
   {en:"Namaste, and good afternoon, everyone. Thank you for giving me this time today.",ja:"ナマステ、皆さん、こんにちは。本日はお時間をいただき、ありがとうございます。"},
   {en:"In the next few minutes, I'd like to introduce myself and my work.",ja:"これから数分で、私自身と私の仕事をご紹介します。"},
   {en:"I'll talk about who I am, where I work, what I do, our strengths, and our plans.",ja:"私が誰か、どこで働いているか、何をしているか、強み、そしてこれからの計画をお話しします。"},
   {en:"First, who I am. My name is Akihiro Iwata, and I'm from Yokohama, Japan.",ja:"まず、私について。岩田章弘と申します。日本の横浜の出身です。"},
   {en:"I'm a licensed acupuncturist and judo therapist. These are national licenses in Japan.",ja:"鍼灸師と柔道整復師の資格をもっています。どちらも日本の国家資格です。"},
   {en:"Before I opened my clinic, I worked as an athletic trainer for sports teams.",ja:"院を開く前は、スポーツチームのアスレティックトレーナーとして働いていました。"},
   {en:"I worked with high school, university, company, and professional teams.",ja:"高校、大学、実業団、プロのチームで働きました。"},
   {en:"That work taught me to support people who need to perform at their best.",ja:"その仕事で、力を出しきらなければならない人を支えることを学びました。"},
   {en:"Next, where I work. My clinic is in Ozu, a quiet city in Ehime, on the island of Shikoku.",ja:"次に、働いている場所です。院は四国の愛媛県にある、静かな町、大洲にあります。"},
   {en:"It's near Iyo-Ozu Station. I opened the clinic in October 2018, and now I have four staff members.",ja:"伊予大洲駅の近くです。2018年10月に開業し、今はスタッフが4名います。"},
   {en:"Now, what I do. My work has three main parts.",ja:"では、私の仕事です。主に3つの柱があります。"},
   {en:"The first part is my clinic, Aki Acupuncture and Judo Therapy Clinic.",ja:"1つ目の柱は、私の院、あき鍼灸整骨院です。"},
   {en:"We offer acupuncture, care for injuries and sports injuries, posture and pelvis care, and care after childbirth.",ja:"鍼灸、けがやスポーツ外傷のケア、姿勢と骨盤のケア、産後のケアを行っています。"},
   {en:"The second part is support for other clinics.",ja:"2つ目の柱は、ほかの院への支援です。"},
   {en:"I check my clinic's sales, visits, and return rate every day. To make this easier, I built a booking and customer management system.",ja:"私は院の売上・来院数・再来院率を毎日見ています。それを楽にするために、予約・顧客管理システムを作りました。"},
   {en:"Now I provide this system to partner clinics, and I also give them management advice.",ja:"今はこのシステムを提携院に提供し、経営のアドバイスもしています。"},
   {en:"Good numbers help small clinics make better decisions, without guessing.",ja:"正しい数字があれば、小さな院も推測にたよらず、より良い判断ができます。"},
   {en:"The third part is hospitality consulting in India.",ja:"3つ目の柱は、インドでのおもてなしのコンサルティングです。"},
   {en:"I help hotels, restaurants, and clinics welcome Japanese guests, and Indian guests who love Japan, with true omotenashi.",ja:"ホテル、レストラン、クリニックが、日本人のお客様や日本好きのインドのお客様を、本物のおもてなしで迎えるお手伝いをしています。"},
   {en:"I also work for my family's business, Odani Sake Ten, a sake shop founded in 1957.",ja:"また、家族の事業である、1957年創業の酒店、小谷酒店でも働いています。"},
   {en:"There, I'm the International Affairs Manager.",ja:"そこでは国際担当をしています。"},
   {en:"So, what are our strengths? I'd like to mention three.",ja:"では、私たちの強みは何でしょうか。3つお伝えします。"},
   {en:"First, I'm a hands-on practitioner. I treat patients every day, so my advice comes from real experience.",ja:"1つ目に、私は現場の施術者です。毎日患者さんを診ているので、助言は本当の経験から来ています。"},
   {en:"Second, I use numbers. My system shows clearly what is working and what is not.",ja:"2つ目に、数字を使います。私のシステムは、何がうまくいき、何がいっていないかをはっきり示します。"},
   {en:"Third, I understand both Japan and India, because I visit India regularly and work with partners here.",ja:"3つ目に、日本とインドの両方を理解しています。定期的にインドを訪れ、こちらのパートナーと仕事をしているからです。"},
   {en:"Finally, our plans for the future.",ja:"最後に、これからの計画です。"},
   {en:"I want to build long-term partnerships in India, step by step, with people who share our values.",ja:"同じ思いをもつ方々と、インドで一歩ずつ、長いおつきあいを築きたいと考えています。"},
   {en:"Looking ahead, I'd like to start with a small project, learn together, and grow from there.",ja:"これからは、小さな事業から始め、一緒に学び、そこから大きくしていきたいです。"},
   {en:"The thing I value most is simple: I do my best for the person in front of me.",ja:"私が一番大切にしていることは簡単です。目の前の人に全力を尽くすことです。"},
   {en:"That's a short introduction to who we are. Thank you for listening, and I'd be happy to answer any questions.",ja:"以上、私たちの短いご紹介でした。お聞きいただきありがとうございました。どんなご質問にもお答えします。"}
  ]},
  task:"インドの取引先とのオンライン商談の最初に、誰が→どこで→何を→強み→これから、の型で自分と事業を4〜5分で紹介する。",
  taskEn:"At the start of an online business meeting with an Indian partner, introduce yourself and your work in four to five minutes. Use the order: who, where, what, strengths, and future plans.",
  qa:[
   {q:"What exactly is a judo therapist?",a:"It's a national license in Japan. Judo therapists treat injuries such as sprains and strains, without surgery.",ja:"質問：柔道整復師とは具体的に何ですか。／答え：日本の国家資格です。ねんざや肉ばなれなどのけがを、手術をせずに施術します。"},
   {q:"Why are you interested in India?",a:"I visit India regularly, and I see a real need for Japanese-style hospitality here.",ja:"質問：なぜインドに関心があるのですか。／答え：定期的にインドを訪れていて、日本式のおもてなしへの本当の必要を感じるからです。"},
   {q:"How do you manage so many kinds of work?",a:"They are all connected. In every job, I try to do my best for the person in front of me.",ja:"質問：たくさんの仕事をどうやってこなしているのですか。／答え：すべてつながっています。どの仕事でも、目の前の人に全力を尽くすようにしています。"},
   {q:"What kind of project would you like to start with?",a:"A small one. For example, a short staff training at one hotel or restaurant.",ja:"質問：どんな事業から始めたいですか。／答え：小さなものです。たとえば、1つのホテルかレストランでの短いスタッフ研修です。"}
  ],
  check:["5つの型（誰が・どこで・何を・強み・これから）の順に話せたか","My work has three main parts. と数を先に言えたか","日本の資格や地名に、短い説明をつけられたか","強みを3つ、理由つきで言えたか","4〜5分に収まったか（時間を計る）"],
  slide:"1枚に5つの型を横に並べた「目次」を作り、話している所を色で示します。写真は院の外観を1枚だけ入れると伝わりやすいです。"},

 {week:32, level:"B1", length:"4分", title:"数字を伝える",
  skill:"売上・割合・価格・日付を正しく読み、聞き手が迷わない順番で数字を伝えられるようになる。",
  lesson:[
   "英語の数字は3けたごとに区切って読みます。4,850,000 は four million, eight hundred and fifty thousand、短く言うなら 4.85 million（four point eight five million）です。日本語の「万」で考えると間違えやすいので、カンマの位置で thousand・million を決めましょう。",
   "割合は2種類あります。68%から72%になったとき、「4ポイント上がった（four percentage points）」と「約6%上がった（about six percent）」は意味が違います。聞き手が混乱しやすい所なので、どちらの意味か、はっきり言いましょう。about seven out of ten（10人に7人）のように言いかえると、わかりやすくなります。",
   "インドの聞き手には、大きな数を lakh（ラーク＝10万）や crore（クロール＝1000万）で言う習慣があります。26 lakh rupees（260万ルピー）のように聞いたら、メモして確かめましょう。円の金額は、ルピーでだいたいいくらかをそえると親切ですが、為替は毎日変わることも言いそえます。",
   "数字は1枚のスライドに1つか2つ。大事な数字は2回、ゆっくり言います。最後に Let me repeat the key numbers. と、主な数字だけをもう一度並べると、聞き手の頭に残ります。日付は January 1st（ファースト）のように序数で読みます。"
  ],
  structure:[{en:"Period and topic",ja:"いつの、何の数字か"},{en:"Sales",ja:"売上（前年との比べ）"},{en:"Visits and rate",ja:"来院数と再来院率"},{en:"Prices and dates",ja:"価格と日付"},{en:"Repeat key numbers",ja:"主な数字をくり返す"}],
  phrases:[
   {en:"Total sales were 4.85 million yen.",ja:"売上の合計は485万円でした。",note:"4.85 は four point eight five と読む。"},
   {en:"Sales went up by 6.5 percent compared with last year.",ja:"売上は前年に比べて6.5パーセント上がりました。",note:"went up by ＋ 数 ＝「〜だけ上がった」。"},
   {en:"That's about seven out of ten patients.",ja:"患者さんの約10人に7人です。",note:"割合を言いかえて、わかりやすくする。"},
   {en:"It improved by four percentage points.",ja:"4ポイント良くなりました。",note:"percentage points（ポイント）と percent（パーセント）を区別する。"},
   {en:"The price will be 5,500 yen per session, including tax.",ja:"料金は1回5,500円（税込み）になります。",note:"five thousand five hundred。per session ＝「1回あたり」。"},
   {en:"That's roughly 2,000 rupees.",ja:"だいたい2,000ルピーです。",note:"roughly ＝「おおよそ」。円とルピーの両方を伝える。"},
   {en:"The new price starts on January 1st, 2027.",ja:"新しい料金は2027年1月1日から始まります。",note:"January first, twenty twenty-seven と読む。"},
   {en:"We aim for a return rate of 75 percent.",ja:"再来院率75パーセントを目指します。",note:"aim for ＝「〜を目指す」。目標の数字に。"},
   {en:"Let me repeat the key numbers slowly.",ja:"主な数字を、ゆっくりくり返します。",note:"最後のまとめの前に。"},
   {en:"All the numbers are in the handout.",ja:"数字はすべて配布資料に入っています。",note:"聞き手がメモに追われないように。"}
  ],
  model:{title:"3か月の数字の報告（売上・来院数・再来院率・新料金）", time:"4分", note:"数字は練習用の例です。自分の数字に入れかえましょう。", lines:[
   {en:"Good evening, everyone. Today I'll share our numbers from July to September.",ja:"皆さん、こんばんは。今日は7月から9月の数字をお伝えします。"},
   {en:"Please look at the first slide. It shows total sales for the three months. It also shows last year's sales for comparison.",ja:"最初のスライドをご覧ください。3か月の売上の合計です。比べるために、前年の売上も出ています。"},
   {en:"Total sales were 4,850,000 yen. That's four million, eight hundred and fifty thousand yen.",ja:"売上の合計は485万円でした。四百八十五万円です。"},
   {en:"Compared with the same period last year, sales went up by 6.5 percent.",ja:"前年の同じ時期と比べて、売上は6.5パーセント上がりました。"},
   {en:"Six point five percent may sound small, but it's steady growth.",ja:"6.5パーセントは小さく聞こえるかもしれませんが、着実な伸びです。"},
   {en:"In the handout, you can see sales for each month: July, August, and September.",ja:"配布資料では、7月・8月・9月の月ごとの売上を見られます。"},
   {en:"Next, the number of visits. We had 1,320 visits in total, about 440 a month.",ja:"次に来院数です。合計1,320回、1か月あたり約440回でした。"},
   {en:"On our busiest day, September 16th, we saw 38 patients.",ja:"一番忙しかった9月16日には、38人の患者さんを診ました。"},
   {en:"Let me say that number again: thirty-eight patients in one day.",ja:"もう一度言います。1日に38人の患者さんです。"},
   {en:"Now let's look at the most important number: the return rate.",ja:"では、もっとも大切な数字、再来院率を見てみましょう。"},
   {en:"The return rate was 72 percent. In other words, about seven out of ten new patients came back.",ja:"再来院率は72パーセントでした。言いかえると、新しい患者さんの約10人に7人がまた来てくれました。"},
   {en:"Last quarter it was 68 percent, so it improved by four points. That's good progress.",ja:"前の3か月は68パーセントだったので、4ポイント良くなりました。良い前進です。"},
   {en:"Please note that's four percentage points, not four percent.",ja:"ご注意ください。4パーセントではなく、4ポイントです。"},
   {en:"Let me explain the difference, because it often causes confusion.",ja:"よく混乱のもとになるので、違いをご説明します。"},
   {en:"Going from 68 to 72 percent is a rise of four points, but about six percent compared with the old number.",ja:"68から72パーセントへの変化は4ポイントの上昇ですが、前の数字と比べると約6パーセントの上昇です。"},
   {en:"Next, the average spending per visit was 3,670 yen.",ja:"次に、1回あたりの平均の支払いは3,670円でした。"},
   {en:"That's three thousand, six hundred and seventy yen. It rose by about 120 yen from last quarter.",ja:"三千六百七十円です。前の3か月から約120円上がりました。"},
   {en:"For our friends in India, that's roughly 2,000 rupees, but the exchange rate changes every day.",ja:"インドの皆さん向けに言うと、だいたい2,000ルピーですが、為替は毎日変わります。"},
   {en:"Now, a few points about prices for next year. Some prices will change.",ja:"では、来年の料金についていくつかお伝えします。いくつかの料金が変わります。"},
   {en:"From January 1st, 2027, the posture care course will be 5,500 yen per session, including tax.",ja:"2027年1月1日から、姿勢のケアのコースは1回5,500円（税込み）になります。"},
   {en:"That's an increase of 500 yen, or about ten percent.",ja:"500円、約10パーセントの値上げです。"},
   {en:"The prices of the other courses will stay the same, so most patients will not see a change.",ja:"ほかのコースの料金は変わらないので、ほとんどの患者さんには変化はありません。"},
   {en:"We will tell patients one month in advance, by December 1st.",ja:"患者さんには1か月前、12月1日までにお知らせします。"},
   {en:"Finally, here is our goal for the next quarter. From October to December.",ja:"最後に、次の3か月の目標です。10月から12月までです。"},
   {en:"We aim for 1,400 visits and a return rate of 75 percent.",ja:"来院数1,400回、再来院率75パーセントを目指します。"},
   {en:"To reach this goal, we will send a short thank-you message after every first visit.",ja:"この目標のために、初回の来院のたびに短いお礼のメッセージを送ります。"},
   {en:"Let me repeat the key numbers once more, slowly.",ja:"主な数字を、もう一度ゆっくりくり返します。"},
   {en:"Sales: 4.85 million yen. Visits: 1,320. Return rate: 72 percent.",ja:"売上：485万円。来院数：1,320回。再来院率：72パーセント。"},
   {en:"And the new price: 5,500 yen from January 1st.",ja:"そして新しい料金：1月1日から5,500円です。"},
   {en:"For partners in India, I will also add the amounts in rupees and lakh in the handout.",ja:"インドのパートナーのために、配布資料にはルピーとラークでの金額も入れます。"},
   {en:"All the numbers are in the handout, so you don't need to write them down.",ja:"数字はすべて配布資料に入っているので、書き留めなくて大丈夫です。"},
   {en:"Thank you. Do you have any questions about the numbers?",ja:"ありがとうございました。数字について、ご質問はありますか。"}
  ]},
  task:"3か月の院の数字（売上・来院数・再来院率・平均の支払い・新しい料金と開始日）を、提携院とインドのパートナーに向けて4分で報告する。数字は自分の本当の数字か、練習用の例を使う。",
  taskEn:"Report three months of clinic numbers in four minutes: sales, visits, return rate, average spending, and a new price with its start date. Speak to partner clinics and partners in India.",
  qa:[
   {q:"Is the 4.85 million yen before or after tax?",a:"It's before tax. The tax is not included.",ja:"質問：485万円は税抜きですか、税込みですか。／答え：税抜きです。税は含まれていません。"},
   {q:"Can you say the sales in rupees?",a:"It's about 26 lakh rupees. But please check today's exchange rate.",ja:"質問：売上をルピーで言えますか。／答え：約26ラーク（260万）ルピーです。ただ、今日の為替を確かめてください。"},
   {q:"Why are you raising the price?",a:"Our costs have gone up, and we are adding a short home exercise guide to the course.",ja:"質問：なぜ値上げするのですか。／答え：費用が上がったのと、コースに短い自宅での運動の案内を加えるからです。"},
   {q:"Was it four percent or four points?",a:"Four points. The return rate went from 68 to 72 percent.",ja:"質問：4パーセントですか、4ポイントですか。／答え：4ポイントです。再来院率は68から72パーセントになりました。"}
  ],
  check:["大きな数を thousand・million で正しく読めたか","percent と percentage points を言い分けられたか","日付を序数（1st, 16th）で読めたか","円の金額にルピーのおおよそをそえたか","最後に主な数字をゆっくりくり返したか"],
  slide:"1枚に大きな数字を1つだけ置き、下に小さく「前年比 +6.5%」のように比べる数字をそえます。グラフは棒グラフ1つで十分です。"},

 {week:33, level:"B1", length:"4分", title:"日程と段取りを示す",
  skill:"ロードマップのスライドを使い、Phase 1… by the end of… の言い方で、事業の日程と段取りを示せるようになる。",
  lesson:[
   "事業の日程を伝えるときは、全体を3つほどの段階（phase）に分けて話します。最初に The project has three phases. と全体の数を言い、Phase 1 is research. のように1つずつ名前をつけます。各段階では「いつからいつまで」「何をするか」「何ができあがるか」の3つを話しましょう。",
   "期限の言い方は、by（〜までに）と until（〜までずっと）を区別します。By the end of February, I will send a report.（2月末までに報告書を送る）と Phase 1 will run until the end of February.（2月末まで続く）は意味が違います。from January to June（1月から6月まで）もよく使います。",
   "インドと日本の時差は3時間30分で、日本のほうが進んでいます。オンラインの日程を決めるときは、Japan is three and a half hours ahead of India. と言い、日本時間とインド時間の両方を伝えましょう。インドには地域ごとの祭日も多いので、相手の休みを聞いてから日程を決めると喜ばれます。",
   "日程の話は数字が多く、聞き手がついてくるのが大変です。大事な日付は2つか3つにしぼり、two key dates のように数を先に言います。最後に全体を1文でまとめ、Does this schedule work for your team? と確かめて終わりましょう。"
  ],
  structure:[{en:"Overview",ja:"全体（期間と段階の数）"},{en:"Phase 1",ja:"第1段階（調べる）"},{en:"Phase 2",ja:"第2段階（研修）"},{en:"Phase 3",ja:"第3段階（ふりかえり）"},{en:"Key dates and request",ja:"大事な日付とお願い"},{en:"Summary and check",ja:"まとめと確認"}],
  phrases:[
   {en:"Here is our roadmap for the next six months.",ja:"こちらが、これから6か月の計画表です。",note:"ロードマップのスライドを見せるときのひと言。"},
   {en:"The project has three phases.",ja:"この事業は3つの段階に分かれています。",note:"全体の数を先に言う。"},
   {en:"Phase 1 will run from January to the end of February.",ja:"第1段階は1月から2月末まで行います。",note:"run ＝「（期間が）続く」。from A to B で期間を言う。"},
   {en:"By the end of February, I will send you a report.",ja:"2月末までに、報告書をお送りします。",note:"by ＝「〜までに」（期限）。until との違いに注意。"},
   {en:"It will start in March and finish by the end of April.",ja:"3月に始まり、4月末までに終わります。",note:"始まりと終わりを1文で。"},
   {en:"Japan is three and a half hours ahead of India.",ja:"日本はインドより3時間30分進んでいます。",note:"時差の言い方。ahead of ＝「〜より進んでいる」。"},
   {en:"There are two key dates I'd like you to remember.",ja:"覚えておいていただきたい大事な日付が2つあります。",note:"日付の数を先に言う。"},
   {en:"Could you choose a contact person by January 15th?",ja:"1月15日までに担当の方を決めていただけますか。",note:"期限つきのお願い。January fifteenth と読む。"},
   {en:"If anything changes, please let me know as early as possible.",ja:"何か変わることがあれば、できるだけ早くお知らせください。",note:"as early as possible ＝「できるだけ早く」。"},
   {en:"Does this schedule work for your team?",ja:"この日程で、皆さんのチームは大丈夫ですか。",note:"最後に相手の都合を確かめる。"}
  ],
  model:{title:"インドのホテルとのおもてなし事業：6か月のロードマップ", time:"4分", note:"日付・回数は練習用の例です。自分の計画に入れかえましょう。", lines:[
   {en:"Good morning, everyone. Today I'll show you the schedule for our omotenashi project.",ja:"皆さん、おはようございます。今日は、おもてなし事業の日程をお見せします。"},
   {en:"Please look at this slide. It's our roadmap for the next six months, from January to June.",ja:"このスライドをご覧ください。1月から6月までの、これから6か月の計画表です。"},
   {en:"The project has three phases. Let me go through them one by one.",ja:"この事業は3つの段階に分かれています。1つずつご説明します。"},
   {en:"Phase 1 is research. It will run from January to the end of February.",ja:"第1段階は調査です。1月から2月末まで行います。"},
   {en:"During this phase, I will visit your hotel in person and watch how guests are welcomed.",ja:"この段階では、私がホテルを直接訪ね、お客様がどう迎えられているかを見ます。"},
   {en:"I will also talk with five or six staff members and read recent guest reviews.",ja:"また、スタッフ5〜6人と話し、最近のお客様の口コミを読みます。"},
   {en:"I want to understand what your team already does well, not only the problems.",ja:"問題だけでなく、チームがすでにうまくできていることも知りたいのです。"},
   {en:"By the end of February, I will send you a short report with what I found.",ja:"2月末までに、わかったことをまとめた短い報告書をお送りします。"},
   {en:"Phase 2 is training. It will start in March and finish by the end of April.",ja:"第2段階は研修です。3月に始まり、4月末までに終わります。"},
   {en:"We will hold four training sessions, two for the front desk and two for the restaurant team.",ja:"研修は4回行います。フロント向けに2回、レストランのチーム向けに2回です。"},
   {en:"The first two sessions will be in person, and the last two will be online.",ja:"最初の2回は対面で、後の2回はオンラインです。"},
   {en:"In person, we can practice greetings and role play together, which is hard to do online.",ja:"対面なら、あいさつや役になりきった練習を一緒にできます。それはオンラインでは難しいことです。"},
   {en:"For the online sessions, please remember the time difference.",ja:"オンラインの回では、時差を覚えておいてください。"},
   {en:"Japan is three and a half hours ahead of India.",ja:"日本はインドより3時間30分進んでいます。"},
   {en:"So if we start at 2 p.m. in Japan, it will be 10:30 a.m. in India.",ja:"ですから、日本で午後2時に始めると、インドでは午前10時30分です。"},
   {en:"I will always write both times in my emails, so nobody gets confused.",ja:"メールには必ず両方の時間を書くので、誰も迷いません。"},
   {en:"Phase 3 is follow-up. It will run from May to the end of June.",ja:"第3段階はふりかえりです。5月から6月末まで行います。"},
   {en:"In this phase, your team will use what they learned with real guests.",ja:"この段階では、チームが学んだことを本当のお客様に使います。"},
   {en:"Managers can watch and give short, positive feedback after each shift.",ja:"管理職の方は様子を見て、勤務の後に短く前向きな声かけをしてください。"},
   {en:"Every two weeks, we'll have a thirty-minute online check-in to share problems and good stories.",ja:"2週間ごとに30分のオンラインの打ち合わせを行い、困ったことや良かった話を共有します。"},
   {en:"By the end of June, we will look at guest comments again and compare them with January.",ja:"6月末までに、お客様の感想をもう一度見て、1月と比べます。"},
   {en:"Now, there are two key dates I'd like you to remember.",ja:"では、覚えておいていただきたい大事な日付が2つあります。"},
   {en:"First, February 28th, the deadline for the research report.",ja:"1つ目は2月28日、調査の報告書の締め切りです。"},
   {en:"Second, March 10th, the first training day at your hotel. It will be for the front desk team.",ja:"2つ目は3月10日、ホテルでの最初の研修の日です。フロントのチーム向けの回です。"},
   {en:"To keep this schedule, I need one thing from your side.",ja:"この日程を守るために、そちらに1つお願いがあります。"},
   {en:"Could you choose one contact person by January 15th?",ja:"1月15日までに、担当の方を1人決めていただけますか。"},
   {en:"This person will help me book rooms for the training and share information with the staff.",ja:"この方には、研修の部屋の予約と、スタッフへの情報共有を手伝っていただきます。"},
   {en:"It's best if this person can read and reply to email or WhatsApp quickly.",ja:"メールや WhatsApp をすぐに読んで返事ができる方だと一番よいです。"},
   {en:"If anything changes, please let me know as early as possible. We can adjust the plan together.",ja:"何か変わることがあれば、できるだけ早くお知らせください。一緒に計画を調整しましょう。"},
   {en:"Let me sum up. Research until February, training until April, and follow-up until June.",ja:"まとめます。2月まで調査、4月まで研修、6月までふりかえりです。"},
   {en:"I will send this roadmap by email today, so you can share it with your team.",ja:"今日この計画表をメールでお送りしますので、チームで共有してください。"},
   {en:"Does this schedule work for your team?",ja:"この日程で、皆さんのチームは大丈夫ですか。"}
  ]},
  task:"インドのホテルとのおもてなし事業の6か月の計画を、3つの段階に分けたロードマップで4分で説明する。時差と大事な日付2つ、相手へのお願いを入れる。",
  taskEn:"Explain a six-month omotenashi project for a hotel in India using a roadmap with three phases. Include the time difference, two key dates, and one request. About four minutes.",
  qa:[
   {q:"Can Phase 2 start earlier?",a:"Possibly. If the report is ready early, we can start in late February.",ja:"質問：第2段階を早めに始められますか。／答え：できるかもしれません。報告書が早くできれば、2月の終わりに始められます。"},
   {q:"What if a training day falls on a festival?",a:"Then we'll move it. Please tell me your holiday dates, and I'll adjust the plan.",ja:"質問：研修の日がお祭りと重なったら？／答え：そのときは日を変えます。休みの日を教えていただければ、計画を調整します。"},
   {q:"Are the online check-ins for managers only?",a:"No, anyone on the team is welcome. Managers should join at least once a month.",ja:"質問：オンラインの打ち合わせは管理職だけですか。／答え：いいえ、チームの誰でも参加できます。管理職の方は少なくとも月1回参加してください。"},
   {q:"What time will the online sessions be in India?",a:"Usually 10:30 a.m. India time. That's 2 p.m. in Japan.",ja:"質問：オンラインの回はインドでは何時ですか。／答え：ふつうはインド時間の午前10時30分です。日本では午後2時です。"}
  ],
  check:["最初に期間と段階の数を言えたか","各段階で「いつ・何を・何ができるか」を話せたか","by と until を正しく使い分けたか","時差を日本時間とインド時間の両方で言えたか","最後に1文でまとめ、相手の都合を確かめたか"],
  slide:"横に3つの矢印（Phase 1・2・3）を並べ、下に月を書きます。大事な日付2つには旗の印をつけましょう。"},

 {week:34, level:"B1", length:"4分", title:"問題を認めて解決策を示す",
  skill:"問題 → 原因 → 対策 → 再発防止 の順で、トラブルを認めて解決策をはっきり伝えられるようになる。",
  lesson:[
   "トラブルの説明は、最初に謝ることから始めます。I'd like to start by saying sorry. と言い、何が起きたかをかくさずに話しましょう。言いわけを先にすると、聞き手は「責任から逃げている」と感じます。謝る → 問題 → 原因 → 対策 → 再発防止、の順を守ります。",
   "原因は、短く、事実だけを話します。That was our mistake. と自分の側の責任をはっきり認めると、かえって信頼されます。そのうえで、すでにしたこと（現在完了 We have fixed… / We have contacted…）と、これからすること（From now on, we will…）を分けて話しましょう。",
   "再発防止は「3つの約束」にすると伝わりやすくなります。First, Second, Third と番号をつけ、何を・いつ・どうするかを具体的に言います。「気をつけます」だけでは、相手は安心できません。",
   "インドの聞き手とのオンラインの場では、声のトーンも大切です。早口になると、あせっているように聞こえます。ゆっくり、落ち着いて話し、最後に要点を1〜2文でまとめましょう。I want to earn back your trust. のように、関係を大切にしている気持ちを言葉にして締めます。"
  ],
  structure:[{en:"Apology",ja:"お詫び"},{en:"Problem",ja:"問題（何が起きたか）"},{en:"Cause",ja:"原因"},{en:"Actions taken",ja:"すでにした対策"},{en:"Prevention",ja:"再発防止（3つの約束）"},{en:"Summary",ja:"まとめと信頼の回復"}],
  phrases:[
   {en:"I'd like to start by saying sorry.",ja:"まず、お詫びを申し上げます。",note:"謝ることから始める。"},
   {en:"I know this caused stress for your staff.",ja:"スタッフの皆さんにご負担をおかけしたことは承知しています。",note:"相手の困りごとを言葉にして認める。"},
   {en:"Let me explain what happened.",ja:"何が起きたかをご説明します。",note:"問題の説明に入る前のひと言。"},
   {en:"The cause was a wrong setting.",ja:"原因は設定の間違いでした。",note:"原因は短く、事実だけ。"},
   {en:"That was our mistake.",ja:"それは私たちの間違いでした。",note:"責任をはっきり認める。言いわけをしない。"},
   {en:"We fixed the problem within two hours.",ja:"2時間以内に問題を直しました。",note:"within ＝「〜以内に」。すばやく動いたことを伝える。"},
   {en:"We have contacted every patient who was affected.",ja:"影響のあった患者さん全員に連絡しました。",note:"現在完了で「もうしたこと」を伝える。"},
   {en:"To prevent this from happening again, we will test every update.",ja:"二度と起きないように、すべての更新を試験します。",note:"prevent A from ～ing ＝「A が〜するのを防ぐ」。"},
   {en:"From now on, we will tell you three days in advance.",ja:"これからは、3日前にお知らせします。",note:"From now on ＝「これからは」。約束の言い方。"},
   {en:"I want to earn back your trust.",ja:"皆さんの信頼を取り戻したいと思います。",note:"関係を大切にしている気持ちで締める。"}
  ],
  model:{title:"予約システムの不具合のお詫びと対策（提携院向け）", time:"4分", note:"場面と数字は練習用の例です。", lines:[
   {en:"Good evening, everyone. Thank you for joining this meeting at short notice.",ja:"皆さん、こんばんは。急なお知らせにもかかわらず、お集まりいただきありがとうございます。"},
   {en:"I'd like to start by saying sorry. Last week, our booking system caused problems at some of your clinics.",ja:"まず、お詫びを申し上げます。先週、私たちの予約システムが、いくつかの院でご迷惑をおかけしました。"},
   {en:"Let me explain what happened, why it happened, and what we are doing about it.",ja:"何が起きたか、なぜ起きたか、そしてどう対応しているかをご説明します。"},
   {en:"First, the problem. On Monday and Tuesday, some patients were booked into the same time slot.",ja:"まず問題です。月曜と火曜に、何人かの患者さんが同じ時間に予約されてしまいました。"},
   {en:"In total, there were twelve double bookings at four clinics.",ja:"合わせて、4つの院で12件の二重予約がありました。"},
   {en:"Some patients had to wait, and some had to come back on another day.",ja:"待たなければならなかった患者さんや、別の日に来直さなければならなかった患者さんもいました。"},
   {en:"Your front desk staff had to explain the situation and apologize many times.",ja:"受付のスタッフの皆さんは、何度も事情を説明し、謝らなければなりませんでした。"},
   {en:"I know this caused stress for your staff and your patients. I'm very sorry.",ja:"スタッフの皆さんと患者さんにご負担をおかけしたことは承知しています。本当に申し訳ありません。"},
   {en:"Next, the cause. Last weekend, we updated the system to add a new reminder feature.",ja:"次に原因です。先週末、新しいお知らせの機能を加えるために、システムを更新しました。"},
   {en:"During the update, one setting for time slots was changed by mistake.",ja:"更新の途中で、予約の枠の設定が1つ、間違って変わってしまいました。"},
   {en:"Because of this, the system did not check if a time slot was already full.",ja:"そのため、システムが予約の枠がすでに埋まっているかを確かめませんでした。"},
   {en:"So when two patients chose the same time, the system accepted both bookings.",ja:"そのため、2人の患者さんが同じ時間を選ぶと、システムが両方の予約を受けてしまいました。"},
   {en:"We did not test this part carefully enough before the update. That was our mistake.",ja:"更新の前に、この部分を十分に試験していませんでした。それは私たちの間違いでした。"},
   {en:"Now, what we have done so far.",ja:"では、これまでに行ったことです。"},
   {en:"On Tuesday evening, we found the problem and fixed the setting within two hours.",ja:"火曜の夜に問題を見つけ、2時間以内に設定を直しました。"},
   {en:"Since Wednesday, there have been no double bookings.",ja:"水曜日からは、二重予約は起きていません。"},
   {en:"We have checked every booking for the next two months, and all of them are correct.",ja:"この先2か月のすべての予約を確かめ、どれも正しいことを確認しました。"},
   {en:"We have also contacted every patient who was affected and apologized directly.",ja:"また、影響のあった患者さん全員に連絡し、直接お詫びしました。"},
   {en:"For those patients, the next visit will be free, and we will cover this cost. Your clinics will not pay for it.",ja:"その患者さんの次の来院は無料とし、その費用は私たちが負担します。皆さんの院の負担はありません。"},
   {en:"Finally, how we will prevent this from happening again. I have three promises.",ja:"最後に、二度と起きないようにする方法です。3つの約束があります。"},
   {en:"First, we will test every update on a practice system before using it at your clinics.",ja:"1つ目に、すべての更新を、皆さんの院で使う前に練習用のシステムで試験します。"},
   {en:"Second, we will update the system only on Sunday nights, when clinics are closed.",ja:"2つ目に、システムの更新は、院が休みの日曜の夜だけに行います。"},
   {en:"Third, from now on, we will tell you about every update three days in advance.",ja:"3つ目に、これからはすべての更新を3日前にお知らせします。"},
   {en:"The email will explain what is changing and what your staff should check.",ja:"メールでは、何が変わるのか、スタッフが何を確かめればよいかを説明します。"},
   {en:"That way, your staff can check the booking screen carefully the next morning.",ja:"そうすれば、スタッフの皆さんが次の朝に予約の画面をよく確かめられます。"},
   {en:"And if you notice anything strange, please call me directly.",ja:"そして、何かおかしいと思ったら、私に直接お電話ください。"},
   {en:"I will answer any time, even on weekends, until we are sure everything is stable.",ja:"すべてが落ち着いたと確かめられるまで、週末でもいつでも電話に出ます。"},
   {en:"Let me sum up. The problem was double bookings, the cause was a wrong setting, and it is fixed now.",ja:"まとめます。問題は二重予約、原因は設定の間違いで、今は直っています。"},
   {en:"To prevent it, we'll test first, update on Sundays, and tell you in advance.",ja:"防ぐために、先に試験し、日曜に更新し、前もってお知らせします。"},
   {en:"Your trust is the most important thing for us, and I want to earn it back.",ja:"皆さんの信頼は私たちにとって一番大切なもので、それを取り戻したいと思います。"},
   {en:"Next month, I will share a short report, so you can see that the system is working well.",ja:"来月、短い報告書をお送りし、システムがきちんと動いていることをお見せします。"},
   {en:"Thank you for your patience. I'm ready to answer your questions.",ja:"ご辛抱いただき、ありがとうございます。ご質問にお答えします。"}
  ]},
  task:"予約システムの不具合（二重予約）について、提携院に向けて、お詫び→問題→原因→対策→再発防止の3つの約束→まとめ、の順で4分で説明する。",
  taskEn:"Explain a booking system problem (double bookings) to partner clinics in four minutes. Use this order: apology, problem, cause, actions taken, three promises to prevent it, and summary.",
  qa:[
   {q:"How can we be sure it won't happen again?",a:"We will test every update first and tell you three days before. I'll also send you a short checklist.",ja:"質問：二度と起きないと、どうしてわかるのですか。／答え：すべての更新を先に試験し、3日前にお知らせします。短い確認表もお送りします。"},
   {q:"Who pays for the free visits?",a:"We do. Please send me the list of patients, and I'll cover the cost.",ja:"質問：無料の来院の費用は誰が払うのですか。／答え：私たちです。患者さんの一覧を送っていただければ、費用を負担します。"},
   {q:"Will there be another update soon?",a:"Yes, in about two weeks. I'll email you three days before it.",ja:"質問：近いうちにまた更新がありますか。／答え：はい、2週間ほど後です。3日前にメールでお知らせします。"},
   {q:"Can we turn off the new reminder feature?",a:"Yes, you can. I'll show you how in the settings after this meeting.",ja:"質問：新しいお知らせの機能を止められますか。／答え：はい、できます。この会議の後に、設定での止め方をお見せします。"}
  ],
  check:["最初に謝ってから話を始めたか","原因を短く事実だけで言い、That was our mistake. と認めたか","すでにしたこと（現在完了）とこれからすること（will）を分けたか","再発防止を3つの具体的な約束にしたか","ゆっくり落ち着いた声で話せたか（録音で確かめる）"],
  slide:"「問題・原因・対策・再発防止」の4つの箱を1枚に並べ、それぞれ1行で書きます。お詫びの言葉はスライドではなく、自分の口で言いましょう。"},

 {week:35, level:"B1", length:"4〜5分", title:"サービスの特徴と良さ",
  skill:"特徴（feature）→ 良さ（benefit）→ 誰に向いているか、の型で、サービスの価値を伝えられるようになる。",
  lesson:[
   "サービスの紹介でよくある失敗は、特徴を並べるだけで終わることです。「オンラインで予約できます」は特徴（feature）。聞き手が本当に知りたいのは「それで自分は何が楽になるのか」という良さ（benefit）です。特徴を1つ言ったら、必ず So what does this mean for you? と良さにつなげましょう。",
   "良さを言うときは This means… / The benefit is… / This helps you… を使います。良さは、相手の毎日の困りごと（電話が多い・予約に来ない・忙しい日に記録が見られない）と結びつけると、ぐっと伝わります。",
   "最後に「誰に向いているか」と「向いていないか」を言います。It may not be the best choice for… と正直に言うと、かえって信頼されます。何でもできると言うより、合う相手をはっきりさせるほうが、商談は前に進みます。",
   "インドの聞き手には、特徴の数を先に言い（I'll explain four features.）、番号をつけて話しましょう。オンラインでは、1つ話すごとに短い間をとり、最後に4つの特徴と良さを1文ずつ並べてまとめます。デモを見せる約束で締めると、次の一歩につながります。"
  ],
  structure:[{en:"Introduction",ja:"何を紹介するか・特徴の数"},{en:"Feature + benefit (x4)",ja:"特徴と良さ（4つ）"},{en:"Who it is for",ja:"誰に向いているか"},{en:"Who it is not for",ja:"向いていない相手"},{en:"Summary and next step",ja:"まとめとデモの提案"}],
  phrases:[
   {en:"Let me introduce our booking and customer management system.",ja:"私たちの予約・顧客管理システムをご紹介します。",note:"紹介の最初のひと言。"},
   {en:"Feature one is online booking, 24 hours a day.",ja:"特徴の1つ目は、24時間のオンライン予約です。",note:"Feature one is ～ と番号をつけて話す。"},
   {en:"So what does this mean for you?",ja:"では、それは皆さんにとってどういうことでしょうか。",note:"特徴から良さへつなぐ、一番大切な問いかけ。"},
   {en:"The benefit is fewer missed appointments.",ja:"良さは、予約の無断キャンセルが減ることです。",note:"The benefit is ＋ 名詞。"},
   {en:"This means any staff member can give the same quality of care.",ja:"これにより、どのスタッフでも同じ質のケアができます。",note:"This means ＋ 文で、良さを言いかえる。"},
   {en:"This helps you make clear decisions.",ja:"これは、はっきりした判断の助けになります。",note:"help ＋ 人 ＋ 動詞の原形。"},
   {en:"It is a good fit for small clinics.",ja:"小さな院に向いています。",note:"a good fit for ＝「〜に合う」。"},
   {en:"It is especially useful if your phone is always busy.",ja:"電話がいつも鳴っている院に、とくに役立ちます。",note:"especially useful if ＋ 文 で、相手の困りごとを言う。"},
   {en:"It may not be the best choice for large hospitals.",ja:"大きな病院には、一番の選択ではないかもしれません。",note:"向いていない相手を正直に言うと信頼される。"},
   {en:"If this sounds useful, I can show you a live demo.",ja:"役に立ちそうでしたら、実際に動くところをお見せします。",note:"次の一歩の提案で締める。"}
  ],
  model:{title:"予約・顧客管理システムの特徴と良さ（インドのクリニック向け）", time:"4〜5分", note:"", lines:[
   {en:"Hello, everyone. Today I'd like to introduce our booking and customer management system.",ja:"皆さん、こんにちは。今日は私たちの予約・顧客管理システムをご紹介します。"},
   {en:"I'll explain four features. For each one, I'll tell you what it is and how it helps you.",ja:"4つの特徴をご説明します。それぞれ、何なのかと、どう役に立つのかをお話しします。"},
   {en:"At the end, I'll talk about which clinics it suits best.",ja:"最後に、どんな院に一番合うかをお話しします。"},
   {en:"Feature one is online booking, 24 hours a day.",ja:"特徴の1つ目は、24時間のオンライン予約です。"},
   {en:"Patients can book from their phone at any time, even late at night.",ja:"患者さんは、夜遅くでも、いつでもスマートフォンから予約できます。"},
   {en:"So what does this mean for you? Your staff spend less time on the phone.",ja:"では、それは皆さんにとってどういうことでしょうか。スタッフが電話にとられる時間が減ります。"},
   {en:"They can focus on the patients who are in front of them.",ja:"目の前の患者さんに集中できます。"},
   {en:"At a busy clinic, the phone can ring many times an hour. Online booking takes much of that work away.",ja:"忙しい院では、電話が1時間に何度も鳴ります。オンライン予約は、その仕事の多くをなくします。"},
   {en:"Feature two is automatic reminders.",ja:"特徴の2つ目は、自動のお知らせです。"},
   {en:"The day before each visit, the system sends a short message to the patient. It includes the date, the time, and a link to change the booking.",ja:"来院の前の日に、システムが患者さんに短いメッセージを送ります。日付、時間、予約を変えるためのリンクが入っています。"},
   {en:"The benefit is fewer missed appointments. For a small clinic, an empty time slot means lost income.",ja:"良さは、予約の無断キャンセルが減ることです。小さな院にとって、空いた予約の枠は失われた収入です。"},
   {en:"Feature three is the customer record.",ja:"特徴の3つ目は、顧客の記録です。"},
   {en:"For each patient, you can see past visits, treatment notes, and the next booking on one screen.",ja:"患者さんごとに、これまでの来院、施術の記録、次の予約を1つの画面で見られます。"},
   {en:"This means any staff member can give the same quality of care, even on a busy day.",ja:"これにより、忙しい日でも、どのスタッフでも同じ質のケアができます。"},
   {en:"Patients feel that the clinic remembers them, and that builds trust.",ja:"患者さんは院が自分を覚えてくれていると感じ、それが信頼につながります。"},
   {en:"For example, a staff member can ask, how is your knee today? The patient doesn't need to explain again.",ja:"たとえば、スタッフが「今日はひざの具合はいかがですか」と聞けます。患者さんはもう一度説明しなくてすみます。"},
   {en:"Feature four is the daily numbers screen. This one is my favorite.",ja:"特徴の4つ目は、毎日の数字の画面です。これは私の一番のお気に入りです。"},
   {en:"Every evening, you can see sales, the number of visits, and the return rate.",ja:"毎晩、売上・来院数・再来院率を見ることができます。"},
   {en:"You can also compare them with last week or last month in one click.",ja:"先週や先月とも、ワンクリックで比べられます。"},
   {en:"I made this feature first, because I check these three numbers every day at my own clinic.",ja:"私はこの機能を最初に作りました。自分の院で、この3つの数字を毎日見ているからです。"},
   {en:"This helps you make clear decisions. You don't need to guess, because the numbers show you what is working.",ja:"これは、はっきりした判断の助けになります。数字が何がうまくいっているかを示すので、推測しなくてすみます。"},
   {en:"Now, who is this system for?",ja:"では、このシステムは誰に向いているのでしょうか。"},
   {en:"It is a good fit for small clinics with one to ten staff members.",ja:"スタッフが1人から10人ほどの小さな院に向いています。"},
   {en:"It is especially useful if your phone is always busy, or if many patients don't come back after one visit.",ja:"電話がいつも鳴っている院や、1回で来なくなる患者さんが多い院に、とくに役立ちます。"},
   {en:"On the other hand, it may not be the best choice for large hospitals.",ja:"一方で、大きな病院には、一番の選択ではないかもしれません。"},
   {en:"Large hospitals often need many special features, and our system is kept simple on purpose.",ja:"大きな病院は多くの特別な機能を必要とすることが多いですが、私たちのシステムはあえて簡単にしています。"},
   {en:"Simple means your staff can learn it in one day, and patients find it easy to use.",ja:"簡単だから、スタッフは1日で覚えられ、患者さんも使いやすいのです。"},
   {en:"Let me sum up the four features and their benefits.",ja:"4つの特徴とその良さをまとめます。"},
   {en:"Online booking saves staff time. Reminders reduce missed visits.",ja:"オンライン予約はスタッフの時間を節約します。お知らせは無断キャンセルを減らします。"},
   {en:"Customer records build trust. And daily numbers help you make clear decisions.",ja:"顧客の記録は信頼を築きます。そして毎日の数字は、はっきりした判断を助けます。"},
   {en:"If this sounds useful, I can show you a live demo next week. I'll use sample data from a clinic like yours.",ja:"役に立ちそうでしたら、来週、実際に動くところをお見せします。皆さんのような院の見本のデータを使います。"},
   {en:"Thank you. What questions do you have?",ja:"ありがとうございました。どんなご質問がありますか。"}
  ]},
  task:"予約・顧客管理システムを、インドのクリニックに向けて、4つの特徴→それぞれの良さ→向いている院と向いていない院→まとめ、の順で4〜5分で紹介する。院のメニューで同じ型を使ってもよい。",
  taskEn:"Introduce the booking and customer management system to clinics in India in four to five minutes. Explain four features and their benefits, who it is for and not for, and finish with a summary and an offer of a demo.",
  qa:[
   {q:"Can patients without smartphones still book?",a:"Yes. Staff can enter phone bookings into the same system.",ja:"質問：スマートフォンのない患者さんも予約できますか。／答え：はい。電話の予約をスタッフが同じシステムに入れられます。"},
   {q:"Is patient data safe?",a:"We take privacy seriously. Only clinic staff with a password can see the records.",ja:"質問：患者さんの情報は安全ですか。／答え：個人情報は大切に扱っています。パスワードをもつ院のスタッフだけが記録を見られます。"},
   {q:"How long does it take to start using it?",a:"About one week. We set it up, and then I give your staff a short online training.",ja:"質問：使い始めるまでにどれくらいかかりますか。／答え：約1週間です。準備をして、その後スタッフの皆さんに短いオンライン研修をします。"},
   {q:"Why is it not good for large hospitals?",a:"Large hospitals need many special functions. We keep our system simple, so small clinics can use it easily.",ja:"質問：なぜ大きな病院には向かないのですか。／答え：大きな病院は多くの特別な機能が必要です。私たちは小さな院が簡単に使えるよう、システムを簡単にしています。"}
  ],
  check:["特徴を1つ言うたびに、良さにつなげたか","So what does this mean for you? を使えたか","良さを相手の困りごとと結びつけたか","向いている相手と向いていない相手を言えたか","最後に4つを1文ずつまとめ、次の一歩を提案したか"],
  slide:"表を1枚作り、左に特徴、右に良さを書きます（Online booking → Less phone time）。良さの列を太字にすると、伝えたいことが目に入ります。"},

 {week:36, level:"B1", length:"4〜5分", title:"聞き手の理解を確かめる",
  skill:"In other words… / To sum up… などの言い換えとまとめ、確認の問いかけをはさんで、聞き手の理解を確かめながら話せるようになる。",
  lesson:[
   "どんなに良い話でも、聞き手がわかっていなければ伝わりません。プレゼンでは、大事なことを言ったら、すぐに言い換えて（In other words… / To put it another way…）、もう一度別の言葉で伝えます。英語が母語でない聞き手にとって、2つの言い方で聞けるのは大きな助けになります。",
   "話の区切りごとに、確認の問いかけをはさみましょう。Is that clear so far? / Does this make sense? と聞き、オンラインならうなずくかチャットに書いてもらいます。ときどき Can someone give me another example? と聞き手に話してもらうと、本当にわかっているかが確かめられます。",
   "インドの聞き手は、わからなくてもその場で言わないことがあります。だからこそ、こちらから確認をはさむことが大切です。ゆっくり、はっきり話し、大事な所では Let me say that again. と言って、くり返しましょう。",
   "最後は To sum up… で要点を3つに並べ、If you remember only one thing today… と一番大切な1つをしぼって伝えます。聞き手に自分の言葉でまとめてもらうと、理解が深まり、場も温まります。"
  ],
  structure:[{en:"Key idea",ja:"大事な考えを言う"},{en:"Rephrase",ja:"言い換える（In other words…）"},{en:"Check",ja:"確認する（Is that clear?）"},{en:"Example from audience",ja:"聞き手に例を出してもらう"},{en:"Sum up",ja:"まとめる（To sum up…）"}],
  phrases:[
   {en:"In other words, you do it because you care.",ja:"言いかえると、気にかけているからそうするのです。",note:"大事なことを別の言葉で言い直す。"},
   {en:"To put it another way, you read the guest's needs.",ja:"別の言い方をすると、お客様の必要を読み取るのです。",note:"In other words と同じ働き。続けて使わず、交互に。"},
   {en:"What I mean is, the last moment is important.",ja:"私が言いたいのは、最後の瞬間が大切だということです。",note:"自分の言いたいことをはっきりさせる。"},
   {en:"Put simply, service answers the request.",ja:"簡単に言うと、サービスは頼まれたことに応えるものです。",note:"むずかしい話を短くまとめる。"},
   {en:"Is that clear so far?",ja:"ここまでは、よろしいですか。",note:"区切りごとの確認。返事を待つ。"},
   {en:"Does this make sense?",ja:"わかりますか（筋が通っていますか）。",note:"やわらかい確認の言い方。"},
   {en:"Let me say that again, because it's important.",ja:"大切なことなので、もう一度言います。",note:"大事な所をくり返す前のひと言。"},
   {en:"Could someone sum up the three ideas in your own words?",ja:"どなたか、3つの考えをご自分の言葉でまとめていただけますか。",note:"聞き手に話してもらい、理解を確かめる。"},
   {en:"To sum up, there are three ideas.",ja:"まとめると、3つの考えがあります。",note:"最後のまとめの合図。"},
   {en:"If you remember only one thing today, please remember this.",ja:"今日1つだけ覚えるなら、これを覚えてください。",note:"一番大切なことを1つにしぼる。"}
  ],
  model:{title:"インドのレストランのスタッフに「おもてなし」を説明する", time:"4〜5分", note:"名前や場面は練習用の例です。", lines:[
   {en:"Good afternoon, everyone. Today's topic is one Japanese word: omotenashi.",ja:"皆さん、こんにちは。今日の話題は、日本語の1つの言葉、「おもてなし」です。"},
   {en:"Some of you may know this word already, but let me explain it simply.",ja:"この言葉をすでにご存じの方もいるかもしれませんが、簡単にご説明します。"},
   {en:"Omotenashi means caring for guests from the heart, without expecting anything back.",ja:"おもてなしとは、見返りを求めずに、心からお客様を大切にすることです。"},
   {en:"You can see it in Japanese hotels, restaurants, and even small shops.",ja:"日本のホテルやレストラン、小さなお店でも見ることができます。"},
   {en:"In other words, you don't do it for a tip or a good review. You do it because you care.",ja:"言いかえると、チップや良い口コミのためにするのではありません。気にかけているからするのです。"},
   {en:"Is that clear so far? Please nod, or type yes in the chat.",ja:"ここまでは、よろしいですか。うなずくか、チャットに yes と書いてください。"},
   {en:"Thank you. Now, the first idea: noticing before guests ask.",ja:"ありがとうございます。では、1つ目の考え、お客様が頼む前に気づくことです。"},
   {en:"For example, a guest looks around the table. Maybe they are looking for a napkin or some water.",ja:"たとえば、お客様がテーブルの周りを見回しています。ナプキンか水を探しているのかもしれません。"},
   {en:"With omotenashi, a staff member notices this and brings it before the guest has to ask.",ja:"おもてなしでは、スタッフがそれに気づき、お客様が頼む前に持っていきます。"},
   {en:"The guest doesn't need to wave or call out. They simply feel looked after.",ja:"お客様は手を振ったり、呼んだりする必要がありません。ただ、大切にされていると感じます。"},
   {en:"To put it another way, you read the guest's needs from small signs.",ja:"別の言い方をすると、小さなしぐさからお客様の必要を読み取るのです。"},
   {en:"Let me check. Can someone give me another example of noticing before a guest asks?",ja:"確かめさせてください。お客様が頼む前に気づく例を、どなたか1つ挙げていただけますか。"},
   {en:"Thank you, Priya. Yes, offering a cushion to an older guest is a perfect example. She noticed the need from a small sign.",ja:"プリヤさん、ありがとうございます。はい、年配のお客様にクッションをお出しするのは、ぴったりの例です。小さなしぐさから必要に気づいていますね。"},
   {en:"Now, the second idea: the same care for everyone. This one is simple, but not always easy.",ja:"では、2つ目の考え、誰にでも同じように心をくばることです。簡単なことですが、いつもできるとは限りません。"},
   {en:"This means every guest gets the same warm welcome, whether they order a cup of tea or a large dinner.",ja:"これは、お茶1杯の方にも、豪華な夕食の方にも、同じ温かい歓迎をするということです。"},
   {en:"Let me say that again, because it's important. Every guest, every time.",ja:"大切なことなので、もう一度言います。どのお客様にも、毎回です。"},
   {en:"The third idea is the farewell. In Japan, we often see guests off at the door and bow until they leave.",ja:"3つ目の考えはお見送りです。日本では、よく入口までお客様をお見送りし、見えなくなるまでおじぎをします。"},
   {en:"What I mean is, the last moment is as important as the first moment.",ja:"私が言いたいのは、最後の瞬間も、最初の瞬間と同じくらい大切だということです。"},
   {en:"Guests remember how you said goodbye.",ja:"お客様は、どう見送られたかを覚えています。"},
   {en:"Even after a perfect dinner, a cold goodbye can leave a bad feeling. A warm goodbye makes them want to return.",ja:"完璧な夕食の後でも、冷たいお見送りはいやな気持ちを残します。温かいお見送りは、また来たいと思わせます。"},
   {en:"Does this make sense? Is there anything I should explain again? Please don't worry about asking.",ja:"わかりますか。もう一度説明したほうがいいことはありますか。遠慮せずに聞いてください。"},
   {en:"Some people ask me, is omotenashi the same as good service?",ja:"「おもてなしは良いサービスと同じですか」と聞かれることがあります。"},
   {en:"Good question. Good service follows the rules. Omotenashi goes one step further. It thinks about what the guest might need next.",ja:"良い質問です。良いサービスは決まりに従います。おもてなしは、さらに一歩先を行きます。お客様が次に何を必要とするかを考えるのです。"},
   {en:"Put simply, service answers the request, and omotenashi answers the feeling.",ja:"簡単に言うと、サービスは頼まれたことに応え、おもてなしは気持ちに応えるのです。"},
   {en:"Let me check once more. In one word, what does omotenashi answer? Yes, the feeling. Exactly.",ja:"もう一度確かめます。ひと言で言うと、おもてなしは何に応えるのでしょうか。そう、気持ちです。そのとおりです。"},
   {en:"So, to sum up, there are three ideas.",ja:"では、まとめると、3つの考えがあります。"},
   {en:"First, notice before guests ask. Second, give the same care to everyone. Third, make the farewell special.",ja:"1つ目、お客様が頼む前に気づく。2つ目、誰にでも同じように心をくばる。3つ目、お見送りを特別なものにする。"},
   {en:"If you remember only one thing today, please remember this: watch the guest, not the menu.",ja:"今日1つだけ覚えるなら、これを覚えてください。メニューではなく、お客様を見ること。"},
   {en:"When you watch the guest carefully, you will know what to do next.",ja:"お客様をよく見ていれば、次に何をすればよいかがわかります。"},
   {en:"Before we finish, could someone sum up the three ideas in your own words?",ja:"終わる前に、どなたか3つの考えをご自分の言葉でまとめていただけますか。"},
   {en:"Great, Arjun. That's exactly right. Thank you.",ja:"すばらしい、アルジュンさん。まさにそのとおりです。ありがとうございます。"},
   {en:"Let's take five minutes for questions, and then we'll practice with role play. We'll work in pairs, one guest and one staff member.",ja:"5分間ご質問をお受けして、その後、役になりきった練習をしましょう。お客様役とスタッフ役の2人1組で行います。"}
  ]},
  task:"インドのレストランのスタッフに「おもてなし」の3つの考えを4〜5分で説明する。大事な所ごとに言い換えと確認をはさみ、最後に聞き手にまとめてもらう。",
  taskEn:"Explain three ideas of omotenashi to restaurant staff in India in four to five minutes. After each key point, rephrase it and check understanding. At the end, ask someone to sum up in their own words.",
  qa:[
   {q:"Isn't it expensive to give so much attention to every guest?",a:"Not really. Most omotenashi is about attention, not money. A smile and a glass of water cost very little.",ja:"質問：すべてのお客様にそんなに気をくばるのは、お金がかかりませんか。／答え：それほどでもありません。おもてなしの多くはお金ではなく、気くばりです。笑顔と1杯の水は、ほとんどお金がかかりません。"},
   {q:"How can we notice guests' needs when we are very busy?",a:"Start small. Choose one table each shift and watch it carefully.",ja:"質問：とても忙しいとき、どうやってお客様の必要に気づけますか。／答え：小さく始めましょう。勤務ごとに1つのテーブルを選んで、よく見てください。"},
   {q:"Does this work for Indian guests too?",a:"Yes. India already has a similar idea: Atithi Devo Bhava, the guest is god.",ja:"質問：これはインドのお客様にも通じますか。／答え：はい。インドにはすでに同じような考え、「アティティ・デーヴォー・バヴァ（客は神なり）」があります。"},
   {q:"Should we bow like Japanese staff?",a:"A small bow is nice for Japanese guests. But a warm smile and namaste also show the same heart.",ja:"質問：日本のスタッフのようにおじぎをしたほうがいいですか。／答え：日本人のお客様には軽いおじぎが喜ばれます。でも、温かい笑顔とナマステでも同じ心が伝わります。"}
  ],
  check:["大事なことを言うたびに、別の言葉で言い換えたか","区切りごとに確認の問いかけをはさんだか","聞き手に例やまとめを話してもらえたか","To sum up… で3つにまとめられたか","一番大切な1つを最後にしぼって言えたか"],
  slide:"3つの考えを3つの絵（目・ハート・手を振る人）で見せ、文字は少なくします。最後のスライドに「Watch the guest, not the menu.」の1文だけを大きく。"},

 {week:37, level:"B1", length:"4〜5分", title:"つかみの話で始める",
  skill:"問いかけ・短いストーリー・身近な話題（アイスブレイク）で、聞き手の心をつかんでからプレゼンを始められるようになる。",
  lesson:[
   "プレゼンの最初の30秒で、聞き手は「この話を聞くかどうか」を決めます。いきなり本題に入るより、短い問いかけやストーリーで始めると、聞き手は自分のこととして話を聞き始めます。これを「つかみ」と言います。",
   "つかみには3つの型があります。1つ目は問いかけ（How many of you…? / What makes you…?）、2つ目は短いストーリー（Let me tell you a short story.）、3つ目は身近な話題のアイスブレイク（天気・食べ物・お茶）です。インドの聞き手なら、チャイの話題は親しみやすく、場がなごみます。",
   "ストーリーは本当の話を使いましょう。小谷酒店が1957年から続いていること、院で患者さんを覚えていることなど、自分の経験から話すと、言葉に力が出ます。作り話は、質問されたときに答えられず、信頼を失います。",
   "つかみで使った問いかけには、最後にもう一度もどります（Let's go back to my first question.）。最初と最後がつながると、話がきれいにまとまり、聞き手の心に残ります。オンラインでは、問いかけの後に、手を挙げるかチャットに書いてもらう時間を少しとりましょう。"
  ],
  structure:[{en:"Icebreaker",ja:"アイスブレイク（身近な話題）"},{en:"Hook question",ja:"つかみの問いかけ"},{en:"Short story",ja:"短いストーリー"},{en:"Topic and main points",ja:"今日の話題と3つの考え"},{en:"Back to the question",ja:"最初の問いにもどって締める"}],
  phrases:[
   {en:"Before we start, let me ask you a quick question.",ja:"始める前に、ちょっとした質問をさせてください。",note:"つかみの問いかけに入る合図。"},
   {en:"How many of you have had chai today?",ja:"今日、チャイを飲んだ方はどれくらいいますか。",note:"How many of you ～? で聞き手に手を挙げてもらう。"},
   {en:"Please think about it for a moment.",ja:"少し考えてみてください。",note:"問いかけの後に、考える時間をとる。"},
   {en:"What makes you go back to the same shop?",ja:"何があなたを同じ店に何度も向かわせるのでしょうか。",note:"make ＋ 人 ＋ 動詞の原形 ＝「人に〜させる」。"},
   {en:"Let me tell you a short story.",ja:"短いお話をさせてください。",note:"ストーリーに入る合図。"},
   {en:"Have you ever felt that a shop remembered you?",ja:"店に覚えてもらえていると感じたことはありますか。",note:"Have you ever ～? で経験を聞く。"},
   {en:"Imagine that a shop owner remembers your name.",ja:"店の主人があなたの名前を覚えていると想像してみてください。",note:"Imagine that ＋ 文。聞き手の頭に場面を浮かばせる。"},
   {en:"So how does a small shop stay open for so long?",ja:"では、小さな店はどうやってそんなに長く続くのでしょうか。",note:"ストーリーの中で、答えを考えさせる問い。"},
   {en:"That's today's topic.",ja:"それが今日の話題です。",note:"つかみから本題へつなぐひと言。"},
   {en:"Let's go back to my first question.",ja:"最初の質問にもどりましょう。",note:"最後に最初の問いにもどり、話をまとめる。"}
  ],
  model:{title:"「なぜお客様はまた来るのか」― 酒店と院の話から", time:"4〜5分", note:"", lines:[
   {en:"Hello, everyone. Before we start, let me ask you a quick question.",ja:"皆さん、こんにちは。始める前に、ちょっとした質問をさせてください。"},
   {en:"How many of you have had chai already today? Please raise your hand or type in the chat.",ja:"今日もうチャイを飲んだ方はどれくらいいますか。手を挙げるか、チャットに書いてください。"},
   {en:"Wow, almost everyone! In Japan, I usually start my day with green tea. But in India, I always enjoy chai.",ja:"わあ、ほとんど全員ですね。日本では、ふだん緑茶で1日を始めます。でもインドでは、いつもチャイを楽しんでいます。"},
   {en:"Here's another question, and please think about it for a moment.",ja:"もう1つ質問です。少し考えてみてください。"},
   {en:"What makes you go back to the same shop again and again?",ja:"何があなたを、同じ店に何度も向かわせるのでしょうか。"},
   {en:"Is it the price? The quality? Or is it something else?",ja:"値段でしょうか。品質でしょうか。それとも、ほかの何かでしょうか。"},
   {en:"Let me tell you a short story.",ja:"短いお話をさせてください。"},
   {en:"My family runs a small sake shop in Japan called Odani Sake Ten. It opened in 1957.",ja:"私の家族は、日本で小谷酒店という小さな酒店を営んでいます。1957年に開いた店です。"},
   {en:"That's almost seventy years ago. And the shop is still open today.",ja:"もう70年近く前のことです。そして店は今も続いています。"},
   {en:"Over the years, shopping has changed a lot.",ja:"その間に、買い物のしかたは大きく変わりました。"},
   {en:"Today, people can buy almost anything online, often at a lower price.",ja:"今では、ほとんど何でもネットで、しかも安く買えることが多いです。"},
   {en:"So how does a small shop stay open for almost seventy years?",ja:"では、小さな店はどうやって70年近くも続いているのでしょうか。"},
   {en:"The answer is simple. People come back.",ja:"答えは簡単です。お客様がまた来てくれるからです。"},
   {en:"And they come back not only for the sake, but for the people and the conversations.",ja:"そしてお客様は、お酒のためだけでなく、人と会話のために来てくれます。"},
   {en:"Customers ask which sake goes well with fish, or what to bring to a family dinner. Those small talks build trust.",ja:"お客様は、魚に合うお酒はどれか、家族の夕食に何を持っていけばよいかをたずねます。その小さな会話が信頼を築きます。"},
   {en:"I see the same thing at my clinic. Patients come back when they feel remembered.",ja:"私の院でも同じことを感じます。患者さんは、覚えてもらえていると感じると、また来てくれます。"},
   {en:"That's today's topic: how to make customers want to come back.",ja:"それが今日の話題、お客様に「また来たい」と思ってもらう方法です。"},
   {en:"I'd like to share three simple ideas. They work in a sake shop, a clinic, a hotel, or a restaurant.",ja:"3つの簡単な考えをお伝えします。酒店でも、院でも、ホテルでも、レストランでも使えます。"},
   {en:"The first idea is to remember one small thing about each customer. Just one thing is enough to start.",ja:"1つ目の考えは、お客様1人ひとりについて、小さなことを1つ覚えることです。始めは1つだけで十分です。"},
   {en:"It could be their favorite drink, their child's name, or a problem they had last time.",ja:"好きな飲み物、お子さんの名前、前回困っていたことなどです。"},
   {en:"You don't need a perfect memory. Simple notes in your customer records are enough.",ja:"完璧な記憶はいりません。顧客の記録に簡単なメモがあれば十分です。"},
   {en:"Next time, you can ask, how is your shoulder now? That one question shows you care.",ja:"次のときに「肩の具合はいかがですか」と聞けます。その1つの質問が、気にかけていることを伝えます。"},
   {en:"The second idea is to make the first visit easy. The first visit is often the hardest step for a new customer.",ja:"2つ目の考えは、初めての来店を気楽なものにすることです。初めての来店は、新しいお客様にとって一番むずかしい一歩であることが多いのです。"},
   {en:"Clear prices, simple booking, and a warm greeting take away the worries of a new customer.",ja:"わかりやすい値段、簡単な予約、温かいあいさつが、初めてのお客様の不安を取りのぞきます。"},
   {en:"The third idea is to say thank you after the visit. Not only at the counter, but later too.",ja:"3つ目の考えは、来店の後にお礼を伝えることです。お店の中だけでなく、その後にもです。"},
   {en:"A short message or a small handwritten note can stay in someone's memory for a long time.",ja:"短いメッセージや小さな手書きのメモは、長く人の記憶に残ります。"},
   {en:"For a hotel, it could be a card in the room. For a clinic, a message the next day.",ja:"ホテルなら部屋に置くカード、院なら次の日のメッセージです。"},
   {en:"None of these ideas cost much money. They cost attention. And attention is something every one of us can give.",ja:"どの考えも、お金はあまりかかりません。かかるのは、気くばりです。そして気くばりは、私たちの誰もが差し出せるものです。"},
   {en:"Let's go back to my first question. What makes you go back to the same shop?",ja:"最初の質問にもどりましょう。何があなたを同じ店に向かわせるのでしょうか。"},
   {en:"I think, for most of us, the answer is a person, not a product.",ja:"私たちの多くにとって、答えは商品ではなく、人だと思います。"},
   {en:"So, starting today, let's try to be that person for our customers.",ja:"ですから今日から、お客様にとってのそんな人になってみましょう。"},
   {en:"Thank you for listening. Now I'd love to hear your own stories. Who would like to share first?",ja:"お聞きいただきありがとうございました。では、皆さん自身のお話もぜひ聞かせてください。最初にお話ししてくださる方はいますか。"}
  ]},
  task:"インドのホテル・レストラン・クリニックの人たちに向けて、アイスブレイク→つかみの問いかけ→自分の本当のストーリー→3つの考え→最初の問いにもどる、の流れで4〜5分話す。",
  taskEn:"Speak for four to five minutes to people from hotels, restaurants, and clinics in India. Start with an icebreaker and a hook question, tell a true short story from your own work, share three ideas, and end by going back to your first question.",
  qa:[
   {q:"How do you remember details about so many customers?",a:"We write short notes in our customer records after each visit. Before the next visit, we read them.",ja:"質問：たくさんのお客様のことを、どうやって覚えているのですか。／答え：来院のたびに、顧客の記録に短いメモを書きます。次の来院の前に、それを読みます。"},
   {q:"What if a customer doesn't want to talk?",a:"That's fine. Respect is also care. A smile and a thank-you are enough.",ja:"質問：お客様が話したくない場合は？／答え：それで大丈夫です。そっとしておくことも気くばりです。笑顔とお礼で十分です。"},
   {q:"Can a big hotel do the same things?",a:"Yes. The team just needs to share notes, so every staff member knows the guest.",ja:"質問：大きなホテルでも同じことができますか。／答え：はい。チームでメモを共有すれば、どのスタッフもお客様のことがわかります。"},
   {q:"Why did you start with chai?",a:"Because it's something we all share. A small common topic helps everyone relax.",ja:"質問：なぜチャイの話から始めたのですか。／答え：みんなに共通するものだからです。小さな共通の話題で、皆さんの気持ちがほぐれます。"}
  ],
  check:["最初の30秒で問いかけかストーリーを入れたか","問いかけの後に、考える・答える時間をとったか","ストーリーは自分の本当の話か","つかみから本題へ That's today's topic. でつなげたか","最後に最初の問いにもどって締めたか"],
  slide:"1枚目は問いかけの1文（What makes you go back?）だけを大きく。2枚目に「1957」の数字と店の写真を1枚入れると、ストーリーが目に浮かびます。"},

 {week:38, level:"B1", length:"30秒×3", title:"短く伝える：30秒のエレベーターピッチ",
  skill:"つかみ → 困りごと → 自分ができること → お願い、の型で、相手に合わせた30秒のピッチを話せるようになる。",
  lesson:[
   "エレベーターピッチとは、エレベーターに乗っている30秒ほどの間に、自分の仕事を伝えて次の約束をもらう短い話のことです。展示会、交流会、オンライン会議の最初など、短い時間しかない場面はたくさんあります。30秒は約70〜80語です。",
   "短くする技術は「1人の相手に、1つのことだけ」です。型は、つかみ（問いかけ）→ 相手の困りごと → 自分ができること（1文）→ 良さ → お願い（次の一歩）。経歴やくわしい説明はすべて捨て、相手が「もっと聞きたい」と思う所で止めます。",
   "岩田さんのように仕事が多い人は、相手ごとにピッチを作り分けましょう。院長には予約システム、ホテルの支配人にはおもてなし、酒の買い手には小谷酒店。全部を30秒に入れようとすると、何も伝わりません。",
   "インドの交流会では、相手も忙しく、周りもにぎやかです。短い文で、はっきり、少しゆっくり話します。最後は必ず質問の形のお願い（Could I…? / Would you be open to…?）で終え、名刺を渡して次の約束につなげましょう。"
  ],
  structure:[{en:"Hook",ja:"つかみ（問いかけ）"},{en:"Problem",ja:"相手の困りごと"},{en:"What I do",ja:"自分ができること（1文）"},{en:"Benefit",ja:"良さ"},{en:"Ask",ja:"お願い（次の一歩）"}],
  phrases:[
   {en:"Do you know your clinic's return rate today?",ja:"今日の院の再来院率をご存じですか。",note:"つかみは相手が答えたくなる問いかけで。"},
   {en:"Many small clinics lose patients without noticing.",ja:"多くの小さな院が、気づかないうちに患者さんを失っています。",note:"相手の困りごとを1文で。"},
   {en:"I help hotels welcome Japanese guests.",ja:"私はホテルが日本人のお客様を迎えるお手伝いをしています。",note:"I help ＋ 相手 ＋ 動詞。自分の仕事を1文で。"},
   {en:"In one sentence, I help clinics keep their patients.",ja:"ひと言で言うと、院が患者さんに来続けてもらうお手伝いをしています。",note:"In one sentence で、短くまとめる合図。"},
   {en:"The goal is guests who come back and recommend you.",ja:"目指すのは、また来て、人にすすめてくれるお客様です。",note:"良さを短く。The goal is ＋ 名詞。"},
   {en:"Here's what I do in thirty seconds.",ja:"私の仕事を30秒でお話しします。",note:"時間を先に言うと、相手が聞きやすい。"},
   {en:"Could I show you a five-minute demo next week?",ja:"来週、5分のデモをお見せしてもいいですか。",note:"お願いは小さく、具体的に。"},
   {en:"Would you be open to a short online meeting?",ja:"短いオンラインの打ち合わせはいかがでしょうか。",note:"be open to ＝「〜を受け入れてもよい」。押しつけない。"},
   {en:"May I give you my card?",ja:"名刺をお渡ししてもいいですか。",note:"ピッチの最後に。"},
   {en:"What's the best way to follow up with you?",ja:"今後のご連絡は、どの方法が一番よいですか。",note:"メールか WhatsApp かを聞き、次につなげる。"}
  ],
  model:{title:"相手ごとの30秒ピッチ（3通り）", time:"30秒×3", note:"", lines:[
   {en:"[Pitch 1: to a clinic owner] Do you know your clinic's return rate today?",ja:"【ピッチ1：院長に】今日の院の再来院率をご存じですか。"},
   {en:"Many small clinics don't, and they lose patients without noticing.",ja:"多くの小さな院は知らず、気づかないうちに患者さんを失っています。"},
   {en:"I'm Akihiro Iwata, an acupuncturist and clinic owner in Japan.",ja:"岩田章弘です。日本で鍼灸師をしながら院を営んでいます。"},
   {en:"I built a simple booking and customer system that shows sales, visits, and return rate every day.",ja:"売上・来院数・再来院率を毎日見せてくれる、簡単な予約・顧客システムを作りました。"},
   {en:"So clinic owners can see what works and act quickly.",ja:"院長は、何がうまくいっているかがわかり、すぐに手を打てます。"},
   {en:"Could I show you a five-minute demo next week?",ja:"来週、5分のデモをお見せしてもいいですか。"},
   {en:"[Pitch 2: to a hotel manager] Japanese guests notice small details, and they remember them.",ja:"【ピッチ2：ホテルの支配人に】日本人のお客様は、小さなことに気づき、それを覚えています。"},
   {en:"I help hotels, restaurants, and clinics in India welcome them with true Japanese omotenashi.",ja:"私はインドのホテル、レストラン、クリニックが、本物の日本のおもてなしでお客様を迎えるお手伝いをしています。"},
   {en:"I watch how your guests are welcomed, and I train your staff with simple, practical steps.",ja:"お客様の迎え方を見て、簡単で実際に使える方法でスタッフを研修します。"},
   {en:"The goal is guests who come back and recommend you.",ja:"目指すのは、また来て、人にすすめてくれるお客様です。"},
   {en:"Would you be open to a short online meeting this month?",ja:"今月、短いオンラインの打ち合わせはいかがでしょうか。"},
   {en:"[Pitch 3: to a buyer at a food event] I'm Akihiro Iwata, International Affairs Manager at Odani Sake Ten.",ja:"【ピッチ3：食品の催しで買い手に】小谷酒店の国際担当、岩田章弘です。"},
   {en:"We are a family sake shop in Japan, open since 1957.",ja:"1957年から続く、日本の家族の酒店です。"},
   {en:"We know Japanese sake well, and we care about matching each sake with the right food.",ja:"日本酒をよく知っていて、それぞれのお酒に合う料理を組み合わせることを大切にしています。"},
   {en:"I'd love to share Japanese sake culture with people who enjoy good food.",ja:"おいしい食べ物が好きな方々に、日本酒の文化をお伝えしたいと思っています。"},
   {en:"May I give you my card? What's the best way to follow up with you?",ja:"名刺をお渡ししてもいいですか。今後のご連絡は、どの方法が一番よいですか。"}
  ]},
  task:"相手を3人決め（院長・ホテルの支配人・酒の買い手など）、それぞれに30秒（約70〜80語）のピッチを作る。時間を計り、30秒を超えたら言葉を削る。",
  taskEn:"Choose three listeners, such as a clinic owner, a hotel manager, and a sake buyer. Give each one a thirty-second pitch of about seventy to eighty words. Time yourself and cut words if you go over thirty seconds.",
  qa:[
   {q:"That sounds interesting. How much does it cost?",a:"It depends on the size of your clinic. Can I ask a few questions in the demo and then send you a quote?",ja:"質問：おもしろそうですね。費用はいくらですか。／答え：院の大きさによります。デモのときにいくつか質問させていただき、その後お見積もりをお送りしてもいいですか。"},
   {q:"Can you send me something to read?",a:"Of course. I'll email you a one-page summary today.",ja:"質問：読めるものを送ってもらえますか。／答え：もちろんです。今日、1枚のまとめをメールでお送りします。"},
   {q:"We already have a booking system.",a:"That's great. Our focus is the daily numbers. Could I show you that part only?",ja:"質問：うちにはもう予約システムがあります。／答え：それはいいですね。私たちの強みは毎日の数字です。その部分だけお見せしてもいいですか。"}
  ],
  check:["1つのピッチが30秒（約70〜80語）に収まったか","つかみの問いかけで始められたか","自分ができることを1文で言えたか","相手ごとに中身を変えたか","最後を質問の形のお願いで終えられたか"],
  slide:"ピッチにはスライドを使いません。代わりに、名刺の裏に3つのピッチの最初の1文だけを書いておくと、本番で迷いません。"},

 {week:39, level:"B1", length:"5分", title:"第3期の発表：5分のオンライン商談プレゼン",
  skill:"第3期で学んだこと（資料の確認・画面共有・会社紹介・数字・日程・良さ・まとめ・お願い）を合わせて、5分のオンライン商談プレゼンができるようになる。",
  lesson:[
   "第3期のしめくくりは、5分のオンライン商談プレゼンです。流れは、音と画面の確認 → ひと言の雑談 → 資料の確認 → 目的 → 自己紹介 → 相手の課題 → 提案（段階と日程）→ 良さ → 費用 → まとめ → 次の一歩。これまで13週で練習した表現を、1つの話にまとめます。",
   "商談プレゼンで一番大切なのは、目的を最初に言うことです。The purpose of today's meeting is to propose… と、30秒以内に言いましょう。聞き手は「何を決めるための会議か」がわかると、ずっと聞きやすくなります。最後は必ず、相手に決めてほしい次の一歩（期限つき）で締めます。",
   "インドの聞き手とのオンライン商談では、はっきり・ゆっくり・要点を先に・確認をはさむ、の4つを守りましょう。費用の数字はルピーと lakh の両方で言い、2回くり返します。話の途中で Is that clear so far? と一度確かめ、最後は画面共有を止めて、顔を見て質問を受けます。",
   "本番の前に、5分を計って3回通しで練習し、録音を聞いて、早口になっている所、言葉につまる所に印をつけましょう。完璧な英語より、落ち着いて相手の目を見て話すことのほうが、信頼につながります。"
  ],
  structure:[{en:"Tech check and small talk",ja:"音・画面の確認とひと言の雑談"},{en:"Purpose and agenda",ja:"目的と流れ"},{en:"About me",ja:"短い自己紹介"},{en:"Problem",ja:"相手の課題"},{en:"Proposal and plan",ja:"提案（3つの段階）"},{en:"Benefits, cost, next step",ja:"良さ・費用・次の一歩"}],
  phrases:[
   {en:"Can you all hear me clearly?",ja:"皆さん、私の声ははっきり聞こえますか。",note:"第29週。最初の確認。"},
   {en:"I sent you the slides by email yesterday.",ja:"昨日、スライドをメールでお送りしました。",note:"第27週。資料の確認。"},
   {en:"The purpose of today's meeting is to propose a pilot project.",ja:"今日の会議の目的は、試しの事業をご提案することです。",note:"目的は最初の30秒で。pilot project ＝「試しの事業」。"},
   {en:"Here is my proposal.",ja:"私の提案はこちらです。",note:"提案に入る合図。"},
   {en:"What does this mean for you?",ja:"それは皆さんにとって、どういうことでしょうか。",note:"第35週。良さへつなぐ。"},
   {en:"You can try this with low risk.",ja:"少ないリスクで試していただけます。",note:"小さく始める提案の強み。"},
   {en:"As for the cost, the pilot is 4.5 lakh rupees in total.",ja:"費用については、試しの事業は合計45万ルピーです。",note:"As for ～ ＝「〜については」。lakh で言うと伝わりやすい。"},
   {en:"This includes my visits and four training sessions.",ja:"これには私の訪問と4回の研修が含まれます。",note:"何が含まれるかをはっきり言う。"},
   {en:"As a next step, could you choose one hotel by the end of this month?",ja:"次の一歩として、今月末までにホテルを1つ選んでいただけますか。",note:"期限つきの次の一歩で締める。"},
   {en:"Thank you for your time. I'm happy to answer any questions.",ja:"お時間をいただきありがとうございました。どんなご質問にもお答えします。",note:"最後のひと言。共有を止めてから言う。"}
  ],
  model:{title:"インドのホテルグループへの、おもてなし試行事業の提案", time:"5分", note:"数字は練習用の例です。自分の数字に入れかえましょう。", lines:[
   {en:"Good afternoon, everyone. Can you all hear me clearly?",ja:"皆さん、こんにちは。私の声ははっきり聞こえますか。"},
   {en:"Thank you. Let me share my screen. Can everyone see the first slide?",ja:"ありがとうございます。画面を共有します。皆さん、最初のスライドが見えますか。"},
   {en:"Great. It's raining here in Ozu today, but I hear it's sunny in Bengaluru. I'm a little jealous.",ja:"よかったです。今日の大洲は雨ですが、ベンガルールは晴れだと聞きました。少しうらやましいです。"},
   {en:"Before we begin, I sent you the slides by email yesterday. Please feel free to follow along.",ja:"始める前に、昨日スライドをメールでお送りしました。どうぞ見ながらついてきてください。"},
   {en:"The purpose of today's meeting is to propose a small pilot project for your hotels. At the end, I will ask you for one small decision.",ja:"今日の会議の目的は、皆さんのホテルに小さな試しの事業をご提案することです。最後に、1つの小さなご判断をお願いします。"},
   {en:"I'll talk for about five minutes, and then we'll have time for questions. If anything is unclear, please stop me at any time.",ja:"約5分お話しし、その後に質問の時間をとります。わかりにくいことがあれば、いつでも止めてください。"},
   {en:"First, let me briefly introduce myself.",ja:"まず、簡単に自己紹介をさせてください。"},
   {en:"I'm Akihiro Iwata. I run an acupuncture clinic in Japan, and I also support hotels, restaurants, and clinics in India.",ja:"岩田章弘です。日本で鍼灸の院を営みながら、インドのホテル、レストラン、クリニックのお手伝いもしています。"},
   {en:"My focus is omotenashi. It means caring for guests from the heart, and noticing their needs before they ask.",ja:"私の専門はおもてなしです。心からお客様を大切にし、頼まれる前に必要なことに気づくことです。"},
   {en:"Now, let me share what I learned from your guest comments last month. Thank you for sending them.",ja:"では、先月いただいたお客様の感想からわかったことをお伝えします。送っていただき、ありがとうございました。"},
   {en:"Your staff are friendly and skilled, and many guests said so in their comments.",ja:"スタッフの皆さんは親切で腕もよく、多くのお客様が感想でそう書いています。"},
   {en:"However, a few Japanese guests mentioned small things. I want to share them because they are easy to fix.",ja:"ただ、何人かの日本人のお客様が、小さなことを書いていました。すぐに直せることなので、お伝えしたいと思います。"},
   {en:"For example, they could not find clear information in the room, and checkout felt a little rushed.",ja:"たとえば、部屋にわかりやすい案内が見つからなかったことや、チェックアウトが少し急かされるように感じたことです。"},
   {en:"These are small points, but Japanese guests notice small points, and they remember them.",ja:"小さなことですが、日本人のお客様は小さなことに気づき、それを覚えています。"},
   {en:"When they share their experience with friends, these small points can decide whether others choose your hotel.",ja:"お客様が友人に体験を話すとき、この小さなことが、ほかの人がホテルを選ぶかどうかを決めることがあります。"},
   {en:"So here is my proposal: a three-month pilot project at one of your hotels.",ja:"そこで私の提案です。皆さんのホテルの1つで、3か月の試しの事業を行います。"},
   {en:"Phase 1, in the first month, I'll visit, watch, and talk with your staff. I will also read guest comments from the past year.",ja:"第1段階、最初の1か月は、私が訪問し、様子を見て、スタッフと話します。この1年のお客様の感想も読みます。"},
   {en:"Phase 2, in the second month, I'll run four training sessions for the front desk and restaurant teams. Each session is about three hours, with plenty of practice.",ja:"第2段階、2か月目は、フロントとレストランのチームに4回の研修を行います。各回は約3時間で、練習をたっぷり行います。"},
   {en:"Phase 3, in the third month, we'll check guest comments together and adjust. At the end, I will send you a clear report with the results.",ja:"第3段階、3か月目は、一緒にお客様の感想を確かめ、やり方を調整します。最後に、結果をまとめたわかりやすい報告書をお送りします。"},
   {en:"Is that clear so far? Good. Now, what does this mean for you? Let me give you three benefits.",ja:"ここまでは、よろしいですか。よかったです。では、皆さんにとってどういうことか、3つの良さをお伝えします。"},
   {en:"First, your staff will feel more confident with Japanese guests, and with Indian guests who love Japan.",ja:"1つ目に、スタッフが、日本人のお客様や日本好きのインドのお客様に、自信をもって接せられるようになります。"},
   {en:"Second, better comments and reviews can bring more guests through recommendations. In the hotel business, a good recommendation is the best kind of advertising.",ja:"2つ目に、より良い感想や口コミが、すすめによって、より多くのお客様を呼べます。ホテルの仕事では、良いすすめが一番の宣伝です。"},
   {en:"Third, you can try this with low risk, because it starts small at only one hotel. If you are happy with the results, we can talk about your other hotels.",ja:"3つ目に、1つのホテルだけで小さく始めるので、少ないリスクで試していただけます。結果にご満足いただければ、ほかのホテルについてもお話しできます。"},
   {en:"As for the cost, the pilot is 450,000 rupees in total. That's 4.5 lakh rupees. Let me repeat: 4.5 lakh rupees.",ja:"費用については、試しの事業は合計45万ルピーです。4.5ラークルピーです。くり返します。4.5ラークルピーです。"},
   {en:"This includes my visits, the four training sessions, and an online check-in every two weeks.",ja:"これには、私の訪問、4回の研修、2週間ごとのオンラインの打ち合わせが含まれます。"},
   {en:"My travel costs are also included, so there are no extra charges.",ja:"私の交通費も含まれているので、追加の費用はありません。"},
   {en:"Let me sum up. One hotel, three months, three phases, and a clear report at the end.",ja:"まとめます。1つのホテル、3か月、3つの段階、そして最後にわかりやすい報告書です。"},
   {en:"In other words, it's a small step to see real results before you make a bigger decision.",ja:"言いかえると、大きな決断をする前に、本当の結果を見るための小さな一歩です。"},
   {en:"As a next step, could you choose one hotel and one contact person by the end of this month?",ja:"次の一歩として、今月末までに、ホテルを1つと担当の方を1人決めていただけますか。"},
   {en:"If that works for you, we can start in January. The first visit could be in the second week of January.",ja:"それでよろしければ、1月に始められます。最初の訪問は1月の第2週にできます。"},
   {en:"I'll stop sharing my screen now, so we can talk face to face.",ja:"では画面の共有を止めますので、顔を見てお話ししましょう。"},
   {en:"Thank you very much for your time. I'm happy to answer any questions.",ja:"お時間をいただき、本当にありがとうございました。どんなご質問にもお答えします。"}
  ]},
  task:"インドのホテルグループに、おもてなしの試しの事業（3か月・3段階）を提案する5分のオンライン商談プレゼンをする。音と画面の確認から始め、目的・自己紹介・課題・提案・良さ・費用・次の一歩まで入れ、最後に質疑応答を受ける。",
  taskEn:"Give a five-minute online sales presentation to a hotel group in India. Propose a three-month omotenashi pilot project. Include a tech check, the purpose, a short self-introduction, the problem, the plan, benefits, cost, and a clear next step. Then take questions.",
  qa:[
   {q:"Why only one hotel?",a:"Starting small lets us learn together. If it works, we can expand to your other hotels.",ja:"質問：なぜホテル1つだけなのですか。／答え：小さく始めると、一緒に学べます。うまくいけば、ほかのホテルにも広げられます。"},
   {q:"Can the price be lower?",a:"I understand. We could reduce the number of sessions, but I recommend four for real change.",ja:"質問：もっと安くなりませんか。／答え：お気持ちはわかります。研修の回数を減らすことはできますが、本当に変わるには4回をおすすめします。"},
   {q:"What results can we expect?",a:"More confident staff and better guest comments. We'll compare the comments before and after.",ja:"質問：どんな結果が期待できますか。／答え：自信をもったスタッフと、より良いお客様の感想です。前と後の感想を比べます。"},
   {q:"Will the training be in English or Hindi?",a:"I'll run it in English, with simple Japanese phrases. Your managers can help explain in Hindi if needed.",ja:"質問：研修は英語ですか、ヒンディー語ですか。／答え：英語で、簡単な日本語の表現も入れて行います。必要なら、管理職の方にヒンディー語で説明を手伝っていただけます。"}
  ],
  check:["最初の30秒で音・画面・資料を確かめ、目的を言えたか","提案を3つの段階に分け、日程とともに話せたか","良さを3つ、費用をルピーと lakh で言えたか","途中で一度、理解を確かめたか","期限つきの次の一歩で締め、5分に収まったか（録音して確かめる）"],
  slide:"6枚で作ります。①題 ②目的 ③お客様の声（課題）④3つの段階 ⑤良さと費用 ⑥次の一歩。1枚に言いたいことは1つだけにしましょう。"}
]);
